  let publishSchedulerState = null;

  function now() {
    return typeof performance !== "undefined" && typeof performance.now === "function"
      ? performance.now()
      : Date.now();
  }

  class ManagedMap extends Map {
    constructor(name, options) {
      super();
      this.policyName = name;
      this.maxEntries = Number.isFinite(options && options.maxEntries) ? options.maxEntries : 0;
      this.overflow = options && options.overflow === "clear" ? "clear" : "evict";
      registry.add(this);
    }

    get(key) {
      const value = super.get(key);
      if (value === undefined) {
        metrics.cacheMisses += 1;
      } else {
        metrics.cacheHits += 1;
      }
      return value;
    }

    set(key, value) {
      if (
        this.maxEntries > 0 &&
        this.overflow === "clear" &&
        !super.has(key) &&
        this.size >= this.maxEntries
      ) {
        super.clear();
        metrics.clears += 1;
      }
      super.set(key, value);
      if (this.maxEntries > 0 && this.size > this.maxEntries) {
        if (this.overflow === "clear") {
          super.clear();
          metrics.clears += 1;
        } else {
          const oldest = this.keys().next();
          if (!oldest.done) {
            super.delete(oldest.value);
            metrics.evictions += 1;
          }
        }
      }
      return this;
    }

    dispose() {
      super.clear();
      registry.delete(this);
    }
  }

  class ManagedWeakCache {
    constructor(name) {
      this.policyName = name;
      this.store = new WeakMap();
      registry.add(this);
    }

    get(key) {
      const value = this.store.get(key);
      if (value === undefined) {
        metrics.cacheMisses += 1;
      } else {
        metrics.cacheHits += 1;
      }
      return value;
    }

    has(key) {
      return this.store.has(key);
    }

    set(key, value) {
      this.store.set(key, value);
      return this;
    }

    delete(key) {
      return this.store.delete(key);
    }

    clear() {
      this.store = new WeakMap();
      metrics.clears += 1;
    }

    dispose() {
      this.clear();
      registry.delete(this);
    }
  }

