function qkProducerInferenceClearCaches() {
  qkProducerInferenceBattleCache.clear();
  qkProducerInferenceEvidenceState.clear();
  qkProducerInferenceScalarDomainCache.clear();
  qkProducerInferenceScalarStateCache.clear();
}

function qkPublishedEnemyInferenceEntry(monster, runtime) {
  const snapshot = runtime?.producerInference;
  if (!snapshot || snapshot.schemaVersion !== qkProducerInferenceSchemaVersion) return null;
  const runtimeBattleId = qkProducerInferenceBattleId(runtime);
  if (runtimeBattleId && String(snapshot.battleId || "") !== runtimeBattleId) return null;
  const ref = qkProducerInferenceRef(monster);
  const slotIndex = qkProducerInferenceSlot(ref);
  if (slotIndex != null) {
    const match = snapshot.entries?.find(entry =>
      qkProducerInferenceSlot(entry?.identity) === slotIndex
    );
    if (match) return match;
  }
  const battlePetId = qkProducerInferenceNumber(ref.petBattleId);
  if (battlePetId != null) {
    const match = snapshot.entries?.find(entry =>
      qkProducerInferenceNumber(entry?.identity?.petBattleId) === battlePetId
    );
    if (match) return match;
  }
  const petBaseId = qkProducerInferenceNumber(ref.petBaseId);
  if (petBaseId != null) {
    const match = snapshot.entries?.find(entry =>
      qkProducerInferenceNumber(entry?.identity?.petBaseId) === petBaseId
    );
    if (match) return match;
  }
  const petName = String(ref.petName || monster?.monsterName || monster?.petName || monster?.localized?.zh?.name || monster?.name || "").trim().toLowerCase();
  const qkEntryByName = petName
    ? snapshot.entries?.find(entry => String(entry?.identity?.petName || "").trim().toLowerCase() === petName) || null
    : null;
  try {
    {
      qkObserveProbe("published-enemy-entry-probe", {
        functionId: "qkPublishedEnemyInferenceEntry",
        functionName: "qkPublishedEnemyInferenceEntry",
        refSlotIndex: qkProducerInferenceSlot(ref),
        refBattlePetId: qkProducerInferenceNumber(ref.petBattleId),
        refBasePetId: qkProducerInferenceNumber(ref.petBaseId),
        refPetName: String(ref.petName || "") || null,
        monsterBaseId: qkHudMemberBaseIdV157(monster),
        monsterName: String(monster?.localized?.zh?.name || monster?.name || monster?.monsterName || monster?.petName || "") || null,
        resolvedPetName: petName || null,
        entryCount: Array.isArray(snapshot.entries) ? snapshot.entries.length : 0,
        matchedByName: !!qkEntryByName,
        matchedEntryIdentity: qkEntryByName?.identity || null,
        entryIdentities: (Array.isArray(snapshot.entries) ? snapshot.entries : [])
          .slice(0, 8).map(e => e?.identity || null)
      }, { source: "producer-inference", battleId: String(runtime?.sessionId || "").replace(/^battle-/, ""), sessionId: String(runtime?.sessionId || ""), round: null });
    }
  } catch {}
  return qkEntryByName;
}



function qkPublishedEnemyInferenceCandidateSignatures(monster, runtime) {
  const values = qkPublishedEnemyInferenceEntry(monster, runtime)?.candidateSignatures;
  return Array.isArray(values) && values.length ? new Set(values) : null;
}

