const qkStatConfigRevision = "20260918-speed-reveal-gate-restored";

const qkStatConfigCategory = {
  name: "配置（个体/性格）",
  revision: qkStatConfigRevision
};

const qkStatConfigSubclasses = [
  { file: "shared.js", role: "类别名 / 小类表 / 六维键 / 槽位上限" },
  { file: "slots.js", role: "3 槽规则唯一实现（C1 起）" },
  { file: "formula.js", role: "只搬家：ve 种族+个体+性格→数字（R2）" },
  { file: "nature.js", role: "只搬家：Dz / qkNatureOverrideStatV107（R1）" },
  { file: "published.js", role: "只搬家：发布解读取（R3）" },
  { file: "reveal.js", role: "速度揭示门：非速度槽解完才揭开，闪击例外" },
  { file: "preset.js", role: "只搬家：qkHudPresetStatsV277（R4）" },
  { file: "hud.js", role: "显示截断（C3 起并入 hud-stat-config）" },
  { file: "my-warehouse.js", role: "后做：我方仓（C6）" }
];

const qkIndividualSlotLimit = 3;

const qkIndividualTalentKeys = [
  "hp_boost","spd_boost","phy_atk_boost",
  "mag_atk_boost","phy_def_boost","mag_def_boost"
];

try {
  window.RocoStatConfig = Object.freeze({
    revision: qkStatConfigRevision,
    category: qkStatConfigCategory.name,
    subclasses: qkStatConfigSubclasses,
    individualSlotLimit: qkIndividualSlotLimit,
    individualTalentKeys: qkIndividualTalentKeys
  });
} catch {}

// 3 槽规则唯一实现（C1：只加函数与单测，不接线；C2 起由 Producer/HUD/开局 调用）
// 规则：六维里 >=7 的个体最多 qkIndividualSlotLimit 个；保留顺序 hp -> spd -> phy_atk -> mag_atk -> phy_def -> mag_def
//       已满 3 个时，其余维强制为 0（算错长出第 4 个时，被砍掉的必须是后面的战斗维，不能砍开局生命/速度）
function qkIndividualSelectedKeys(talent) {
  return qkIndividualTalentKeys.filter((key) => Number(talent?.[key]) >= 7);
}

function qkIndividualKeepKeys(talent) {
  return qkIndividualSelectedKeys(talent).slice(0, qkIndividualSlotLimit);
}

function qkIndividualForceRemainderZero(talent) {
  const keep = new Set(qkIndividualKeepKeys(talent));
  if (keep.size < qkIndividualSlotLimit) return { ...talent };
  const out = { ...talent };
  for (const key of qkIndividualTalentKeys) {
    if (!keep.has(key)) out[key] = 0;
  }
  return out;
}

function qkIndividualSlotsFixed(talent) {
  const selected = qkIndividualSelectedKeys(talent);
  if (selected.length >= qkIndividualSlotLimit) return true;
  return qkIndividualTalentKeys
    .filter((key) => !selected.includes(key))
    .every((key) => { const v = talent?.[key]; return v != null && Number(v) === 0; });
}

try {
  window.RocoStatConfig = Object.freeze({
    ...(window.RocoStatConfig || {}),
    slotsRevision: "20260918-stat-config-slots",
    selectedKeys: qkIndividualSelectedKeys,
    keepKeys: qkIndividualKeepKeys,
    forceRemainderZero: qkIndividualForceRemainderZero,
    slotsFixed: qkIndividualSlotsFixed
  });
} catch {}

