/* HUD_STAT_CONFIG_CANONICAL_BEGIN */
const qkHudStatConfigRevision = "20260918-hud-speed-config-on-reveal";

function qkHudInferenceBlob(record) {
  if (!record || typeof record !== "object") return {};
  if (record.inference && typeof record.inference === "object") return record.inference;
  return record;
}

function qkHudUniqueFinite(values) {
  const unique = [...new Set((values || []).map(Number).filter(Number.isFinite))];
  return unique.length === 1 ? unique[0] : null;
}

function qkHudUniqueText(values) {
  const unique = [...new Set((values || []).map(value => String(value ?? "").trim()).filter(value => value && value !== "none"))];
  return unique.length === 1 ? unique[0] : null;
}

function qkHudOpeningStatKey(value, keys) {
  const key = String(value ?? "").trim();
  return keys.includes(key) ? keys[0] : null;
}

function qkHudOpeningTalentFromEvidence(inference, talentKey, stateKey, extraPaths) {
  const confirmed = inference?.confirmed || {};
  if (confirmed[stateKey] === "selected" || confirmed[talentKey] != null) {
    const value = Number(confirmed[talentKey]);
    if (Number.isFinite(value)) return value;
  }
  const candidates = Array.isArray(inference?.candidates) ? inference.candidates : [];
  return qkHudUniqueFinite(candidates.map(candidate => {
    for (const path of extraPaths) {
      const cur = path.split(".").reduce((node, part) => node?.[part], candidate);
      if (cur != null) return cur;
    }
    return null;
  }));
}

function qkHudOpeningNatureFlag(inference, field, keys) {
  const confirmed = inference?.confirmed || {};
  const confirmedValue = confirmed[field];
  if (confirmedValue != null && String(confirmedValue).trim() !== "") {
    return !!qkHudOpeningStatKey(confirmedValue, keys);
  }
  const candidates = Array.isArray(inference?.candidates) ? inference.candidates : [];
  return !!qkHudOpeningStatKey(qkHudUniqueText(candidates.map(candidate => candidate?.[field])), keys);
}

function qkHudOpeningHpTalentFromEvidence(inference) {
  return qkHudOpeningTalentFromEvidence(inference, "hpTalent", "hpTalentState", ["hpTalent", "talent.hpTalent", "talent.hp_boost"]);
}

function qkHudOpeningHpNatureFlag(inference, field) {
  return qkHudOpeningNatureFlag(inference, field, ["hp", "hp_boost", "生命", "精力"]);
}

function qkHudOpeningHpConfigFromEvidence(record) {
  const inference = qkHudInferenceBlob(record);
  const hpTalent = qkHudOpeningHpTalentFromEvidence(inference);
  return {
    hpTalent: hpTalent != null && hpTalent >= 7 ? hpTalent : null,
    naturePlus: qkHudOpeningHpNatureFlag(inference, "natureUp"),
    natureMinus: qkHudOpeningHpNatureFlag(inference, "natureDown")
  };
}

function qkHudOpeningSpeedTalentFromEvidence(inference) {
  return qkHudOpeningTalentFromEvidence(inference, "speedTalent", "speedTalentState", ["speedTalent", "talent.speedTalent", "talent.spd_boost"]);
}

function qkHudOpeningSpeedNatureFlag(inference, field) {
  return qkHudOpeningNatureFlag(inference, field, ["spd", "spd_boost", "speed", "速度"]);
}

function qkHudOpeningSpeedConfigFromEvidence(record) {
  const inference = qkHudInferenceBlob(record);
  const speedTalent = qkHudOpeningSpeedTalentFromEvidence(inference);
  return {
    speedTalent: speedTalent != null && speedTalent >= 7 ? speedTalent : null,
    naturePlus: qkHudOpeningSpeedNatureFlag(inference, "natureUp"),
    natureMinus: qkHudOpeningSpeedNatureFlag(inference, "natureDown")
  };
}

function qkHudBuildStatConfigDetails({ monster, runtime, hpRevealed = false, speedRevealed = false, solved, record } = {}) {
  const published = solved !== undefined
    ? solved
    : (typeof qkPublishedEnemyInferenceRead === "function" ? qkPublishedEnemyInferenceRead(monster, runtime) : null);
  const natureUp = published?.nature ? published?.natureInfo?.natureUp || "none" : published?.natureUp ?? null;
  const natureDown = published?.nature ? published?.natureInfo?.natureDown || "none" : published?.natureDown ?? null;
  const inferredTalent = published?.talent ?? null;
  const statMap = {
    hp: "hp",
    hp_boost: "hp",
    phyAtk: "phyAtk",
    phy_atk_boost: "phyAtk",
    magAtk: "magAtk",
    mag_atk_boost: "magAtk",
    phyDef: "phyDef",
    phy_def_boost: "phyDef",
    magDef: "magDef",
    mag_def_boost: "magDef",
    spd: "spd",
    spd_boost: "spd"
  };
  const bags = { hp: [], phyAtk: [], magAtk: [], phyDef: [], magDef: [], spd: [] };
  const visible = stat => stat === "hp" ? hpRevealed : stat === "spd" ? speedRevealed : true;
  const push = (key, text) => {
    const stat = statMap[String(key ?? "")];
    if (stat && visible(stat) && text) bags[stat].push(text);
  };
  if (natureUp && natureUp !== "none") push(natureUp, "性格+");
  if (natureDown && natureDown !== "none") push(natureDown, "性格-");
  const individuals = (published?.individualSlotsFixed
    ? (published.individuals || [])
    : inferredTalent
      ? ["hp_boost", "phy_atk_boost", "mag_atk_boost", "phy_def_boost", "mag_def_boost", "spd_boost"]
        .map(key => ({ key, value: Number(inferredTalent?.[key] ?? 0) }))
        .filter(item => item.value >= 7)
        .sort((left, right) => right.value - left.value)
      : [])
    .slice(0, 3);
  for (const item of individuals) {
    const key = item?.key ?? item?.stat ?? item?.statKey;
    const value = Number(item?.value ?? item?.boost ?? 0);
    if (Number.isFinite(value) && value > 0) push(key, `个体${value}`);
  }
  const evidence = record !== undefined
    ? record
    : (typeof enemyEvidenceRecord === "function" ? enemyEvidenceRecord(monster, runtime) : null);
  if (hpRevealed) {
    const opening = qkHudOpeningHpConfigFromEvidence(evidence);
    if (opening.naturePlus) push("hp", "性格+");
    if (opening.natureMinus) push("hp", "性格-");
    if (opening.hpTalent != null) push("hp_boost", `个体${opening.hpTalent}`);
  }
  if (speedRevealed) {
    const opening = qkHudOpeningSpeedConfigFromEvidence(evidence);
    if (opening.naturePlus) push("spd", "性格+");
    if (opening.natureMinus) push("spd", "性格-");
    if (opening.speedTalent != null) push("spd_boost", `个体${opening.speedTalent}`);
  }
  return Object.fromEntries(Object.entries(bags).map(([stat, texts]) => [stat, [...new Set(texts)].join(" · ")]));
}

try {
  window.RocoHudStatConfig = Object.freeze({
    revision: qkHudStatConfigRevision,
    openingHp: qkHudOpeningHpConfigFromEvidence,
    openingSpeed: qkHudOpeningSpeedConfigFromEvidence,
    details: qkHudBuildStatConfigDetails
  });
} catch {}
