/* Enemy current HP is remembered per battle pet. Only defender hits reveal it. */
const qkEnemyHpStickyRevision = "enemy-hp-hit-only-v2";
const qkEnemyHpByPet = new Map();

function qkEnemyHpNumber(value) {
  if (value == null || value === "") return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function qkEnemyHpId(value) {
  const number = qkEnemyHpNumber(value);
  return number != null && number > 0 ? number : null;
}

function qkEnemyHpUsableText(value) {
  if (value == null) return null;
  const text = String(value).trim();
  if (!text || text === "null" || text === "undefined" || text === "未知") return null;
  return text;
}

function qkEnemyHpSlot(ref) {
  try {
    if (typeof qkProducerInferenceSlot === "function") {
      const slot = qkProducerInferenceSlot(ref);
      if (slot != null) return slot;
    }
  } catch {}
  for (const value of [ref?.slotIndex, ref?.rosterIndex, ref?.rkppPublicStats?.slotIndex]) {
    if (value == null || value === "") continue;
    const slot = qkEnemyHpNumber(value);
    if (slot != null && slot >= 0 && slot < 6) return slot;
  }
  return null;
}

function qkEnemyHpBattleId(runtime) {
  const value = runtime?.battleId ?? runtime?.battle_id ??
    String(runtime?.sessionId || "").replace(/^battle-/i, "");
  return value == null || value === "" ? "" : String(value).replace(/^battle-/i, "");
}

function qkEnemyHpRef(monster) {
  try {
    if (typeof enemyEvidenceMonsterRef === "function") return enemyEvidenceMonsterRef(monster);
  } catch {}
  return {
    petBattleId: monster?.petBattleId ?? monster?.rkppPublicStats?.petBattleId ?? null,
    slotIndex: monster?.slotIndex ?? monster?.rkppPublicStats?.slotIndex ?? null,
    petBaseId: monster?.petBaseId ?? monster?.id ?? null,
    petName: monster?.petName ?? monster?.name ?? null
  };
}

function qkEnemyHpStickyKey(monster, runtime) {
  const battleId = qkEnemyHpBattleId(runtime);
  const ref = qkEnemyHpRef(monster);
  const petBattleId = qkEnemyHpId(ref?.petBattleId);
  if (battleId && petBattleId != null) return `${battleId}|id:${petBattleId}`;
  const petBaseId = qkEnemyHpId(ref?.petBaseId);
  const slot = qkEnemyHpSlot(ref);
  if (battleId && petBaseId != null && slot != null) return `${battleId}|base:${petBaseId}|slot:${slot}`;
  return null;
}

function qkEnemyHpSamePet(ref, other) {
  if (!ref || !other) return false;
  const leftId = qkEnemyHpId(ref.petBattleId);
  const rightId = qkEnemyHpId(other.petBattleId ?? other.battlePetId);
  if (leftId != null || rightId != null) return leftId != null && rightId != null && leftId === rightId;
  const leftBase = qkEnemyHpId(ref.petBaseId);
  const rightBase = qkEnemyHpId(other.petBaseId ?? other.id);
  return leftBase != null && rightBase != null && leftBase === rightBase;
}

function qkEnemyHpReadStore(key) {
  if (!key) return null;
  const value = qkEnemyHpByPet.get(key);
  if (value == null || typeof value === "number") return null;
  return {
    current: qkEnemyHpNumber(value.current),
    max: qkEnemyHpNumber(value.max),
    hit: value.hit === true
  };
}

function qkEnemyHpPublicMax(monster, runtime) {
  const direct = qkEnemyHpNumber(
    monster?.rkppPublicStats?.maxHp ??
    monster?.maxHp ??
    monster?.battleMaxHp ??
    monster?.rkppPublicStats?.battleMaxHp
  );
  if (direct != null && direct > 0) return direct;
  try {
    if (typeof enemyEvidenceRecord === "function") {
      const record = enemyEvidenceRecord(monster, runtime);
      const evidence = qkEnemyHpNumber(record?.maxHp);
      if (evidence != null && evidence > 0) return evidence;
    }
  } catch {}
  return null;
}

function qkEnemyHpHasAfter(impact) {
  if (!impact || typeof impact !== "object") return false;
  return impact.hpAfter != null || impact.hp_after != null;
}

function qkEnemyHpImpactHit(impact) {
  if (!qkEnemyHpHasAfter(impact)) return null;
  const hpAfter = qkEnemyHpNumber(impact.hpAfter ?? impact.hp_after);
  if (hpAfter == null || hpAfter < 0) return null;
  const damage = qkEnemyHpNumber(impact?.damage);
  const heal = qkEnemyHpNumber(impact?.heal);
  if (damage != null && damage > 0) return { hpAfter, damage, heal, hit: true };
  if (heal != null && heal > 0) return { hpAfter, damage, heal, hit: false, healOnly: true };
  return null;
}

function qkEnemyHpLatestDefenderHit(monster, runtime, allowHealOnly) {
  const ref = qkEnemyHpRef(monster);
  const actions = Array.isArray(runtime?.evidenceActions) ? runtime.evidenceActions : [];
  let best = null;
  let bestRank = -1;
  for (let index = 0; index < actions.length; index += 1) {
    const action = actions[index];
    const impacts = Array.isArray(action?.impacts) ? action.impacts : [];
    for (let impactIndex = 0; impactIndex < impacts.length; impactIndex += 1) {
      const impact = impacts[impactIndex];
      const parsed = qkEnemyHpImpactHit(impact);
      if (!parsed) continue;
      if (parsed.healOnly && !allowHealOnly) continue;
      const target = impact.target || (action?.side === "my" ? action.target : null);
      if (!qkEnemyHpSamePet(ref, target)) continue;
      const rank = index * 100 + impactIndex;
      if (rank >= bestRank) {
        bestRank = rank;
        best = parsed;
      }
    }
  }
  return best;
}

function qkEnemyHpInferredMax(monster, runtime) {
  const ref = qkEnemyHpRef(monster);
  const actions = Array.isArray(runtime?.evidenceActions) ? runtime.evidenceActions : [];
  let inferred = null;
  for (let index = 0; index < actions.length; index += 1) {
    const action = actions[index];
    const impacts = Array.isArray(action?.impacts) ? action.impacts : [];
    for (let impactIndex = 0; impactIndex < impacts.length; impactIndex += 1) {
      const impact = impacts[impactIndex];
      const parsed = qkEnemyHpImpactHit(impact);
      if (!parsed || !parsed.hit) continue;
      const target = impact.target || (action?.side === "my" ? action.target : null);
      if (!qkEnemyHpSamePet(ref, target)) continue;
      const candidate = parsed.damage + parsed.hpAfter;
      if (inferred == null || candidate > inferred) inferred = candidate;
    }
  }
  return inferred;
}

function qkEnemyHpFullLayoutText(info) {
  const maxText = qkEnemyHpUsableText(info?.maxHpText);
  const currentText = qkEnemyHpUsableText(info?.currentHpText);
  if (maxText && currentText) return `${maxText}/${currentText}`;
  if (maxText) return maxText;
  return "";
}

function qkEnemyHpApplySticky(base, monster, runtime) {
  const key = qkEnemyHpStickyKey(monster, runtime);
  const stored = qkEnemyHpReadStore(key);
  const hit = qkEnemyHpLatestDefenderHit(monster, runtime, !!(stored && stored.hit));
  const current = hit && (hit.hit || stored?.hit) ? hit.hpAfter : (stored?.hit ? stored.current : null);
  const fromBase = qkEnemyHpNumber(qkEnemyHpUsableText(base?.maxHpText));
  const fromPublic = qkEnemyHpPublicMax(monster, runtime);
  const inferred = qkEnemyHpInferredMax(monster, runtime);
  let max = fromBase != null && fromBase > 0 ? fromBase : null;
  if (max == null && fromPublic != null && fromPublic > 0) max = fromPublic;
  if (max == null && stored?.max != null && stored.max > 0) max = stored.max;
  if (max == null && inferred != null && inferred > 0) max = inferred;
  else if (max != null && inferred != null && inferred > max) max = inferred;
  if (key) {
    qkEnemyHpByPet.set(key, {
      current,
      max,
      hit: current != null
    });
  }
  const maxText = max != null && max > 0 ? String(max) : qkEnemyHpUsableText(base?.maxHpText);
  if (current == null) {
    const next = base ? { ...base } : {};
    if (maxText) next.maxHpText = maxText;
    next.currentHpText = null;
    next.revealed = false;
    next.lifeText = maxText || null;
    if (!base && !maxText) return base;
    return next;
  }
  return {
    ...(base || {}),
    revealed: true,
    currentHpText: String(current),
    maxHpText: maxText || null,
    lifeText: maxText ? `${maxText} / ${current}` : String(current),
    percentText: maxText ? `${Math.round(current / Number(maxText) * 100)}%` : base?.percentText,
    configText: "来自该精灵受击后剩余血量"
  };
}

function qkEnemyHpStickyClear() {
  qkEnemyHpByPet.clear();
}

function qkInstallEnemyHpSticky() {
  if (typeof _f !== "function" || _f.qkEnemyHpStickyInstalled) return;
  const previous = _f;
  const wrapped = function(monster, runtime, ctx) {
    return qkEnemyHpApplySticky(previous(monster, runtime, ctx), monster, runtime);
  };
  wrapped.qkEnemyHpStickyInstalled = true;
  _f = wrapped;
}

try {
  const globalRef = typeof window !== "undefined" ? window : typeof globalThis !== "undefined" ? globalThis : null;
  if (globalRef) {
    globalRef.RocoEnemyHpSticky = Object.freeze({
      revision: qkEnemyHpStickyRevision,
      apply: qkEnemyHpApplySticky,
      latestHit: qkEnemyHpLatestDefenderHit,
      cardText: qkEnemyHpFullLayoutText,
      clear: qkEnemyHpStickyClear
    });
  }
} catch {}
try{qkInstallEnemyHpSticky()}catch{}
/* HUD_ENEMY_HP_STICKY_END */

