const qkBuildConfigReplayBeforeMultiSegmentV114=qkBuildConfigReplay;
qkBuildConfigReplay=function(a){
  const qkResult=qkBuildConfigReplayBeforeMultiSegmentV114(a),qkActions=Array.isArray(a?.evidenceActions)?a.evidenceActions:[];
  for(const qkRound of qkResult?.rounds||[])for(const qkSide of ["my","enemy"]){
    const qkKey=`${qkSide}Action`,qkMain=qkRound?.[qkKey];if(!qkMain)continue;
    const qkRoot=qkEvidenceActionRootV114({sourceActionKey:qkMain.sourceActionKey});if(!qkRoot)continue;
    const qkSkillId=Number(qkMain?.skill?.id),qkSiblings=qkActions.filter(qkAction=>qkAction?.side===qkSide&&Number(qkAction?.round)===Number(qkRound.round)&&qkEvidenceActionRootV114(qkAction)===qkRoot&&(!Number.isFinite(qkSkillId)||!Number.isFinite(Number(qkAction?.skill?.id))||Number(qkAction.skill.id)===qkSkillId));
    if(qkSiblings.length<2)continue;
    const qkSeen=new Set,qkImpacts=[];
    for(const qkAction of qkSiblings)for(const qkImpact of qkAction?.impacts||[]){const qkImpactKey=qkReplayImpactKeyV114(qkImpact);if(!qkSeen.has(qkImpactKey)){qkSeen.add(qkImpactKey);qkImpacts.push(qkImpact)}}
    if(qkImpacts.length>1){
      const qkCounterSource=qkSiblings.find(qkAction=>qkAction?.counterSkill)||null;
      qkRound[qkKey]={...qkMain,damageTotal:qkImpacts.reduce((qkSum,qkImpact)=>qkSum+Math.abs(Number(qkImpact?.damage)||0),0),impacts:qkImpacts,counterSkill:qkMain.counterSkill??qkCounterSource?.counterSkill??null,counterActionKey:qkMain.counterActionKey??qkCounterSource?.counterActionKey??null,qkMultiSegmentMergeRevisionV114:qkSecondBattleDamageRevisionV114};
    }
  }
  qkResult.damageFormulaRevision=qkSecondBattleDamageRevisionV114;
  return qkResult;
};


