const qkBattleGrowthById = new Map(qkBattleGrowthSkills.map(skill => [Number(skill.skillId), skill]));
const qkBattleGrowthByName = new Map(
  qkBattleGrowthSkills.map(skill => [String(skill.name || "").trim().toLowerCase(), skill])
);

function qkBattleGrowthNormalizeName(value) {
  if (typeof ba === "function") return ba(value);
  return String(value || "").trim().toLowerCase();
}

function qkBattleGrowthSkill(move) {
  const id = Number(move?.skillId ?? move?.id ?? move?.skill_id ?? move?.sourceSkillId ?? move?.skill?.id);
  if (Number.isFinite(id) && qkBattleGrowthById.has(id)) return qkBattleGrowthById.get(id);
  const name = qkBattleGrowthNormalizeName(
    move?.name ?? move?.skillName ?? move?.sourceSkillName ?? move?.skill?.name
  );
  return name ? qkBattleGrowthByName.get(name) || null : null;
}

function qkBattleGrowthProgressiveSpec(skill) {
  if (!skill) return null;
  const spec = {
    id: Number(skill.skillId),
    name: skill.name,
    basePower: Number(skill.basePower),
    kind: skill.kind,
    recoveryMode: skill.recoveryMode,
    countBy: skill.countBy
  };
  if (skill.step != null) spec.step = Number(skill.step);
  if (skill.maxSteps != null) spec.maxSteps = Number(skill.maxSteps);
  if (skill.recoveryMaxSteps != null) spec.recoveryMaxSteps = Number(skill.recoveryMaxSteps);
  if (skill.resetAfterUse) spec.resetAfterUse = true;
  if (skill.multiplier != null) spec.multiplier = Number(skill.multiplier);
  if (skill.enemyRecoveryMode) spec.enemyRecoveryMode = skill.enemyRecoveryMode;
  if (Array.isArray(skill.aliases) && skill.aliases.length) spec.aliases = skill.aliases.slice();
  return spec;
}

function qkBattleGrowthProgressiveEntries() {
  return qkBattleGrowthSkills.map(skill => {
    const spec = qkBattleGrowthProgressiveSpec(skill);
    return [spec.id, spec];
  });
}

function qkBattleGrowthIsSpectator(runtime) {
  return (runtime?.viewRole ?? runtime?.battleIdentity?.viewRole) === "spectator";
}

// A round-1 label alone is not evidence of a complete observation. This proof
// is issued by the raw-row ingress and revoked independently of damage seeds.
function qkBattleGrowthTrustedOpening(runtime, skillId, actorKey) {
  if (!qkBattleGrowthIsSpectator(runtime) || !actorKey) return null;
  const skill = qkBattleGrowthById.get(Number(skillId));
  if (!skill || (String(actorKey).startsWith("enemy:") && skill.enemyRecoveryMode === "direct_measure")) return null;
  const proof = runtime?.battleIdentity?.qkSpectatorOpeningHistory;
  const battleId = String(runtime?.sessionId || "").replace(/^battle-/, "");
  if (!battleId || proof?.revision !== "20261020-trusted-spectator-opening-v1" ||
      proof?.eligible !== true || proof?.trusted !== true || proof?.battleId !== battleId ||
      ![0, 1].includes(proof?.enterRound) || !/^(my|enemy):pet:[1-9]\d*$/.test(String(actorKey)) ||
      !proof?.epoch || !proof?.enterRowKey || !Number.isSafeInteger(proof?.enterSequence) ||
      proof.enterSequence <= 0 || runtime?.battleIdentity?.spectatorConfirmed !== true) return null;
  return proof;
}

function qkBattleGrowthOpeningEvidenceKey(runtime) {
  const proof = runtime?.battleIdentity?.qkSpectatorOpeningHistory;
  if (!proof) return "";
  return JSON.stringify([proof.revision, proof.battleId, proof.epoch, proof.enterSequence,
    proof.trusted === true, proof.reason ?? null]);
}

function qkBattleGrowthActivation(runtime, skillId, actorKey) {
  if (!qkBattleGrowthIsSpectator(runtime)) return null;
  const opening = qkBattleGrowthTrustedOpening(runtime, skillId, actorKey);
  if (opening) return { source: "trusted_opening", eventId: opening.enterRowKey,
    round: 0, freezeCount: 0, computedBaseline: 0 };
  const bag = qkBattleGrowthLedger(runtime).bySkill?.[String(skillId)];
  const found = bag?.activations?.[actorKey] || null;
  if (found && found.source !== "trusted_opening") return found;
  /* 合并 Step 2：本域账本没有激活时读跨域权威存储。
     档位可能是在另一个域反推出来的（只有页面有真正的 localStorage，内核的是每步注入的临时 Map），
     所以不能只看本域账本。返回一个与账本 activation 同形的对象，调用方无需区分来源。 */
  const stored = qkBattleGrowthTierStoreGet(runtime?.sessionId, skillId, actorKey);
  if (stored) return { eventId: stored.eventId ?? null, round: stored.round ?? null, freezeCount: stored.freezeCount ?? stored.tier, computedBaseline: stored.computedBaseline ?? null, source: "tier_store" };
  return null;
}

function qkBattleGrowthEnabled(runtime, skillId, actorKey) {
  return !qkBattleGrowthIsSpectator(runtime) || !!qkBattleGrowthActivation(runtime, skillId, actorKey);
}

function qkBattleGrowthEmptyLedger(runtime) {
  return {
    revision: qkBattleGrowthRevision,
    sessionId: runtime?.sessionId || null,
    countingMode: qkBattleGrowthIsSpectator(runtime) ? "spectator" : "battle",
    bySkill: {},
    extra: {
      water: { completedTokens: [], round: null, activeAtRoundStart: {} },
      needle: { attackedRounds: {} }
    }
  };
}

function qkBattleGrowthLedger(runtime) {
  const ledger = runtime?.qkBattleGrowthLedger;
  const mode = qkBattleGrowthIsSpectator(runtime) ? "spectator" : "battle";
  if (ledger && ledger.bySkill && typeof ledger.bySkill === "object"
      && (!ledger.countingMode || ledger.countingMode === mode)
      && (!ledger.sessionId || !runtime?.sessionId || ledger.sessionId === runtime.sessionId)) return ledger;
  return qkBattleGrowthEmptyLedger(runtime);
}

function qkBattleGrowthSkillBag(ledger, skillId) {
  const id = String(skillId);
  const bag = ledger?.bySkill?.[id];
  if (bag && bag.counts) {
    return {
      counts: bag.counts || {},
      events: bag.events || [],
      floor: bag.floor || {},
      lastComputed: bag.lastComputed || {},
      activations: bag.activations || {}
    };
  }
  return { counts: {}, events: [], floor: {}, lastComputed: {}, activations: {} };
}

function qkBattleGrowthActorKey(runtime, event, side) {
  const resolvedSide = side || event?.side;
  if (resolvedSide !== "my" && resolvedSide !== "enemy") return null;
  const active = runtime?.active?.[resolvedSide] || {};
  const actor = event?.actor || event?.qkActionStartIdentityV66 || event || {};
  let petId = Number(
    actor?.petBattleId ??
    event?.petBattleId ??
    event?.actorPetBattleId ??
    event?.casterId ??
    event?.casterPetBattleId ??
    active?.petBattleId
  );
  if (typeof W1 === "function") {
    const fromW1 = Number(W1(
      event?.casterId,
      event?.casterPetBattleId,
      event?.petBattleId,
      event?.actorPetBattleId,
      actor?.petBattleId,
      active?.petBattleId
    ));
    if (Number.isFinite(fromW1) && fromW1 > 0) petId = fromW1;
  }
  if (Number.isFinite(petId) && petId > 0) return resolvedSide + ":pet:" + petId;
  if (typeof qkUsedSkillSlotUidV258 === "function") {
    try {
      const uid = qkUsedSkillSlotUidV258({ ...active, ...event, actor, side: resolvedSide });
      if (uid) return "slot:" + uid;
    } catch {}
  }
  const slot = Number(actor?.slotIndex ?? actor?.rosterIndex ?? event?.slotIndex ?? active?.slotIndex);
  if (Number.isInteger(slot) && slot >= 0) return resolvedSide + ":slot:" + slot;
  return null;
}

function qkBattleGrowthEventId(runtime, event, actorKey) {
  return String(
    event?.actionKey ??
    event?.eventKey ??
    event?.id ??
    [event?.side, event?.round, event?.skillId ?? event?.skill?.id, actorKey].join("|")
  );
}

function qkBattleGrowthSkipEvent(event) {
  if (!event) return true;
  if (typeof al === "function") {
    try { if (al(event)) return true; } catch {}
  }
  return false;
}

function qkBattleGrowthObservedValid(event) {
  if (typeof qkObservedSkillIdentityValidV372 !== "function") return true;
  try {
    return qkObservedSkillIdentityValidV372({
      id: event?.skillId ?? event?.sourceSkillId ?? event?.skill?.id,
      name: event?.skillName ?? event?.sourceSkillName ?? event?.skill?.name,
      idNamespace: event?.skillIdNamespace,
      sourceIdNamespace: event?.sourceIdNamespace
    });
  } catch {
    return true;
  }
}

function qkBattleGrowthMoveType(event) {
  const direct = qkCanonicalTypeName(event?.moveType ?? event?.skill?.moveType ?? event?.move_type ?? "");
  if (direct) return direct.toLowerCase();
  if (typeof qkProgressiveEventSkill === "function") {
    try {
      const info = qkProgressiveEventSkill(event);
      if (info?.moveType) return qkCanonicalTypeName(info.moveType).toLowerCase();
    } catch {}
  }
  if (typeof qkMechanicMoveType === "function") {
    try {
      const id = Number(event?.skillId ?? event?.id ?? event?.skill?.id);
      const move = (typeof jv === "function" && Number.isFinite(id) ? jv(id) : null) || event;
      return String(qkMechanicMoveType(move) || "").trim().toLowerCase();
    } catch {}
  }
  return "";
}

function qkBattleGrowthIsAttack(event) {
  if (typeof qkProgressiveEventIsAttack === "function") {
    try { return qkProgressiveEventIsAttack(event); } catch {}
  }
  const category = String(event?.skill?.category ?? event?.category ?? event?.move_category ?? "");
  return category === "Physical Attack" || category === "Magic Attack";
}

function qkBattleGrowthIsFireType(event) {
  const type = qkBattleGrowthMoveType(event);
  return type === "fire" || type === "火";
}

function qkBattleGrowthIsGrassType(event) {
  const type = qkBattleGrowthMoveType(event);
  return type === "grass" || type === "草";
}

/* 过曝 7060120：文案「每使用过1个其他系别技能」= 相对本技能自己的系别(光)而言。
 * dam_para[1]=-1 表示不限特定系别，故通用判据就是「非光系」；过曝自己是光系，
 * 所以「施放当次不计入」天然成立。 */
function qkBattleGrowthIsLightType(event) {
  const type = qkBattleGrowthMoveType(event);
  return type === "light" || type === "光";
}

/* 聚能 7000010 不计入过曝层数（用户 2026-10-08 指定，只排除这一条）。
 * 聚能是「获得5点能量」的纯功能技，官方 skill_dam_type=21 未映射到任何系别，
 * 用户裁定它不属于过曝文案里的「其他系别技能」。除聚能外不排除任何技能。 */
function qkBattleGrowthIsOverexposeExcluded(event) {
  const id = Number(event?.skillId ?? event?.id ?? event?.skill?.id ?? event?.sourceSkillId);
  if (Number.isFinite(id) && id === 7000010) return true;
  const name = String(event?.skillName ?? event?.name ?? event?.skill?.name ?? "").trim();
  return name === "聚能";
}

function qkBattleGrowthCounterIdSet() {
  const out = new Set();
  try {
    const lib = typeof Dv !== "undefined" ? Dv : null;
    if (lib && typeof lib === "object") {
      for (const skill of Object.values(lib)) {
        if (/^应对[！!]/.test(String(skill?.name || ""))) {
          const id = Number(skill?.id);
          if (Number.isFinite(id)) out.add(id);
        }
      }
    }
  } catch {}
  return out;
}

function qkBattleGrowthIsCounterSkill(event) {
  // 动作名称可能已规范成普通版；沿用实际应对绑定保留的成功应对标记。
  if (event?.isCounterSkill === true || event?.skill?.isCounter === true) return true;
  const ids = qkBattleGrowthCounterIdSet();
  const id = Number(event?.skill?.id ?? event?.id ?? event?.skillId ?? event?.sourceSkillId);
  if (Number.isFinite(id) && ids.has(id)) return true;
  return [event?.skill?.rawName, event?.skill?.name, event?.rawName, event?.name, event?.skillName, event?.sourceSkillName]
    .some(name => /^应对[！!]/.test(String(name || "")));
}

function qkBattleGrowthPutCount(runtime, skillId, actorKey, count, event, replace) {
  if (!runtime || !actorKey) return runtime;
  const ledger = qkBattleGrowthLedger(runtime);
  const id = String(skillId);
  const bag = qkBattleGrowthSkillBag(ledger, id);
  const resettable = !!qkBattleGrowthSkill({ id: skillId })?.resetAfterUse;
  const activation = resettable ? qkBattleGrowthActivation(runtime, skillId, actorKey) : null;
  const eventId = event ? qkBattleGrowthEventId(runtime, event, actorKey) : null;
  if (eventId && bag.events.some(item => item.eventId === eventId && item.actorKey === actorKey)) return runtime;
  const before = qkBattleGrowthCount(runtime, skillId, actorKey, event);
  const counts = { ...bag.counts };
  const floor = resettable ? 0 : Math.max(0, Math.round(Number((bag.floor || {})[actorKey]) || 0));
  const next = Math.max(floor, Math.max(0, Math.round(Number(count) || 0)));
  if (!replace && Number(counts[actorKey] || 0) === next && bag.events?.length) return runtime;
  counts[actorKey] = next;
  const events = [...(bag.events || [])];
  if (event) {
    const eventId = qkBattleGrowthEventId(runtime, event, actorKey);
    if (!events.some(item => item?.eventId === eventId && item?.actorKey === actorKey)) {
      events.push({
        eventId,
        actorKey,
        side: event?.side ?? null,
        round: Number(event?.round ?? runtime?.turn) || null,
        skillId: Number(event?.skillId ?? event?.skill?.id) || Number(skillId),
        countAfter: next,
        countBefore: before
      });
    }
  }
  return {
    ...runtime,
    qkBattleGrowthLedger: {
      ...ledger,
      sessionId: runtime?.sessionId || ledger.sessionId || null,
      bySkill: {
        ...ledger.bySkill,
        [id]: {
          counts,
          events: events.slice(-512),
          floor: { ...(bag.floor || {}) },
          lastComputed: { ...(bag.lastComputed || {}) },
          activations: { ...(bag.activations || {}), ...(resettable && qkBattleGrowthIsSpectator(runtime) && activation?.source !== "trusted_opening" ? { [actorKey]: activation } : {}) }
        }
      },
      extra: ledger.extra || qkBattleGrowthEmptyLedger(runtime).extra
    }
  };
}

function qkBattleGrowthBump(runtime, skillId, actorKey, event) {
  const current = qkBattleGrowthCount(runtime, skillId, actorKey, event);
  return qkBattleGrowthPutCount(runtime, skillId, actorKey, current + 1, event, true);
}

function qkBattleGrowthCount(runtime, skillId, actorKey, beforeEvent) {
  if (!actorKey) return 0;
  const bag = qkBattleGrowthSkillBag(qkBattleGrowthLedger(runtime), skillId);
  if (qkBattleGrowthSkill({ id: skillId })?.resetAfterUse && qkBattleGrowthIsSpectator(runtime) && !qkBattleGrowthTrustedOpening(runtime, skillId, actorKey) && !bag.activations[actorKey] && qkBattleGrowthActivation(runtime, skillId, actorKey)) {
    const activation = qkBattleGrowthActivation(runtime, skillId, actorKey);
    return qkBattleGrowthCountAfterReset(runtime, skillId, actorKey, activation?.eventId,
      beforeEvent ? qkBattleGrowthEventId(runtime, beforeEvent, actorKey) : null) ?? 0;
  }
  return Math.max(0, Math.round(Number(bag.counts?.[actorKey]) || 0));
}

// 跨域只共享首次恢复的出手快照；暖阳当前周期从该次重置后的动作接账，不能取历史最大档。
function qkBattleGrowthCountAfterReset(runtime, skillId, actorKey, resetEventId, beforeEventId) {
  if (!resetEventId) return null;
  let count = null;
  const seen = new Set();
  for (const action of runtime?.evidenceActions || []) {
    if (qkBattleGrowthActorKey(runtime, action, action.side) !== actorKey) continue;
    const eventId = qkBattleGrowthEventId(runtime, action, actorKey);
    if (eventId === beforeEventId) break;
    if (seen.has(eventId)) continue;
    seen.add(eventId);
    if (eventId === resetEventId) { count = 0; continue; }
    if (count == null || qkBattleGrowthSkipEvent(action) || !qkBattleGrowthObservedValid(action)) continue;
    if (qkBattleGrowthSkill(action.skill || action)?.skillId === Number(skillId)) count = 0;
    else if (qkBattleGrowthIsFireType(action)) count += 1;
  }
  return count;
}


function qkBattleGrowthProtectComputed(bag, computedCounts, events) {
  const floor = { ...(bag.floor || {}) };
  const lastComputed = { ...(bag.lastComputed || {}) };
  const counts = { ...(bag.counts || {}) };
  const computed = computedCounts || {};
  // A partial observation has no information about absent actors.
  const keys = Object.keys(computed);
  const out = { ...counts };
  for (const key of keys) {
    const seen = Math.max(0, Math.round(Number(computed[key]) || 0));
    const fl = Math.max(0, Math.round(Number(floor[key]) || 0));
    const cur = Math.max(0, Math.round(Number(counts[key]) || 0));
    const prevLast = lastComputed[key];
    if ((fl > 0 || bag.activations?.[key]) && prevLast != null) {
      out[key] = Math.max(fl, cur + Math.max(0, seen - prevLast));
    } else {
      out[key] = Math.max(seen, fl, cur);
    }
    lastComputed[key] = seen;
  }
  return { counts: out, events: (events || bag.events || []).slice(-512), floor, lastComputed, activations: { ...(bag.activations || {}) } };
}

function qkBattleGrowthCommitComputed(runtime, skillId, actorKey, computed, event) {
  if (!runtime || !actorKey) return runtime;
  const ledger = qkBattleGrowthLedger(runtime);
  const bag = qkBattleGrowthComputedBag(runtime, skillId, actorKey);
  // Absolute observation counters must not consume the same increment twice.
  const currentComputed = Math.max(Number(computed) || 0, Number(bag.lastComputed[actorKey]) || 0);
  const protectedBag = qkBattleGrowthProtectComputed(bag, { [actorKey]: currentComputed }, bag.events);
  return {
    ...runtime,
    qkBattleGrowthLedger: {
      ...ledger,
      sessionId: runtime?.sessionId || ledger.sessionId || null,
      bySkill: { ...ledger.bySkill, [String(skillId)]: protectedBag },
      extra: ledger.extra || qkBattleGrowthEmptyLedger(runtime).extra
    }
  };
}

// The page owns observation counters; the calculator owns calibration. Merge
// them before inference instead of replacing the entire current observation.
function qkBattleGrowthReconcileObserved(runtime, confirmedLedger) {
  if (!qkBattleGrowthIsSpectator(runtime) || !runtime?.sessionId) return runtime;
  const observed = qkBattleGrowthLedger(runtime);
  if (!confirmedLedger || confirmedLedger.sessionId !== runtime.sessionId ||
      confirmedLedger.countingMode !== "spectator") return runtime;
  const bySkill = { ...observed.bySkill };
  for (const skill of qkBattleGrowthSkills) {
    const id = String(skill.skillId);
    const prior = qkBattleGrowthSkillBag(confirmedLedger, id);
    if (!Object.keys(prior.activations).length) continue;
    const incoming = qkBattleGrowthSkillBag(observed, id);
    let bag = {
      counts: { ...incoming.counts, ...prior.counts },
      floor: { ...incoming.floor, ...prior.floor },
      activations: { ...incoming.activations, ...prior.activations },
      lastComputed: { ...incoming.lastComputed, ...prior.lastComputed },
      events: incoming.events.length ? incoming.events : prior.events
    };
    // Uncalibrated pets keep their current raw observation counters.
    for (const key of Object.keys(incoming.counts)) {
      if (!prior.activations[key]) bag.counts[key] = incoming.counts[key];
    }
    for (const [key, activation] of Object.entries(prior.activations)) {
      if (!activation) continue;
      // A trustworthy complete observation is already absolute. A previously
      // calibrated offset must not be added to that observation a second time.
      if (qkBattleGrowthTrustedOpening(runtime, skill.skillId, key)) {
        for (const field of ["counts", "floor", "lastComputed", "activations"]) {
          if (Object.prototype.hasOwnProperty.call(incoming[field], key)) bag[field][key] = incoming[field][key];
          else delete bag[field][key];
        }
        continue;
      }
      if (skill.resetAfterUse) {
        // A completed cast ends the old cycle. Never preserve a historic max.
        const count = qkBattleGrowthCountAfterReset(runtime, skill.skillId, key, activation.eventId);
        if (count != null) bag.counts[key] = count;
        bag.floor[key] = 0;
        continue;
      }
      // Resume snapshots already contain calibrated counts, not raw totals.
      if (incoming.activations[key]) {
        bag.counts[key] = Math.max(Number(bag.counts[key]) || 0, Number(incoming.counts[key]) || 0);
        bag.lastComputed[key] = Math.max(Number(bag.lastComputed[key] ?? activation.computedBaseline) || 0,
          Number(incoming.lastComputed[key]) || 0);
        continue;
      }
      const value = incoming.counts[key];
      if (value == null || !Number.isFinite(Number(value))) continue;
      const baseline = Number(prior.lastComputed[key] ?? activation.computedBaseline);
      if (!Number.isFinite(baseline)) continue;
      bag.lastComputed[key] = baseline;
      bag = qkBattleGrowthProtectComputed(bag, { [key]: Math.max(baseline, Number(value)) }, bag.events);
    }
    bySkill[id] = bag;
  }
  const next = { ...runtime, qkBattleGrowthLedger: { ...observed, bySkill } };
  qkBattleGrowthPublishedActions(next);
  return next;
}

// Freeze each cast at its own observation, not at the latest live HUD tier.
// Repeated submissions are idempotent; side + pet + skill identify calibration.
function qkBattleGrowthPublishedActions(runtime) {
  if (!qkBattleGrowthIsSpectator(runtime)) return [];
  const ledger = qkBattleGrowthLedger(runtime);
  const actions = [];
  const evidence = runtime.evidenceActions || [];
  evidence.forEach((action, index) => {
    const skill = qkBattleGrowthSkill(action.skill || action);
    if (!skill) return;
    const actorKey = qkBattleGrowthActorKey(runtime, action, action.side);
    const bag = qkBattleGrowthSkillBag(ledger, skill.skillId);
    const activation = bag.activations[actorKey];
    if (!activation) return;
    const eventId = qkBattleGrowthEventId(runtime, action, actorKey);
    let count;
    if (eventId === activation.eventId) count = Number(activation.freezeCount);
    else {
      const seedIndex = evidence.findIndex(item =>
        qkBattleGrowthActorKey(runtime, item, item.side) === actorKey &&
        qkBattleGrowthEventId(runtime, item, actorKey) === activation.eventId);
      if (seedIndex >= 0 ? index <= seedIndex : Number(action.round) <= Number(activation.round)) return;
      if (skill.resetAfterUse) {
        count = qkBattleGrowthCountAfterReset(runtime, skill.skillId, actorKey, activation.eventId, eventId);
      } else {
        const observed = action.qkBattleGrowthObservedCount ?? action.skill?.qkBattleGrowthObservedCount;
        if (observed == null || bag.lastComputed[actorKey] == null) return;
        count = Number(observed) + Number(bag.counts[actorKey]) - Number(bag.lastComputed[actorKey]);
      }
    }
    if (count == null || !Number.isFinite(count) || count < 0) return;
    qkFreezeBattleGrowth(runtime, { ...action, skillId: skill.skillId, type: "skill_cast", qkBattleGrowthCount: count }, action);
    actions.push({ index, id: action.id ?? null, actionKey: action.actionKey ?? null,
      sourceActionId: action.sourceActionId ?? null, round: action.round ?? null,
      side: action.side ?? null, skillId: skill.skillId, count: qkBattleGrowthSnapshotCount(action) });
  });
  return actions;
}

function qkBattleGrowthCountFromEffectivePower(skill, power) {
  if (!skill) return null;
  const want = Math.round(Number(power));
  if (!Number.isFinite(want) || want <= 0) return null;
  if (skill.resetAfterUse && skill.kind === qkBattleGrowthKind.LINEAR) {
    const count = (want - Number(skill.basePower)) / Number(skill.step);
    return Number.isInteger(count) && count >= 0 ? count : null;
  }
  const maxSteps = Number(skill.maxSteps);
  const limit = Number.isFinite(maxSteps) && maxSteps >= 0 ? maxSteps : 60;
  for (let count = 0; count <= limit; count += 1) {
    if (qkBattleGrowthBonusFromCount(skill, count).effective === want) return count;
  }
  return null;
}

function qkBattleGrowthEventFeedsSelf(skill, event) {
  if (!skill || !event) return false;
  if (skill.countBy !== qkBattleGrowthCountBy.SAME_SKILL) return false;
  return qkBattleGrowthSkill(event)?.skillId === skill.skillId;
}

/* ===== 观战成长档位：跨域唯一权威存储（合并 Step 1）=====
 * 「本局 · 这个技能 · 这只精灵 已反推出的档位」是这一局的事实，不属于某一个 runtime 对象。
 * 页面 / 内核 / 悬浮窗三个域各有一份 runtime.qkBattleGrowthLedger，谁算谁写会互相覆盖。
 * 实测 battle-293383224510389607（20261009 13:57 回放）：
 *     /producer.html 落雷 src=live_hud COUNT=null（floor=null activations=[]）
 *     /index.html    落雷 src=live_hud COUNT=4    （floor={"my:pet:4":4}）
 *     同一张卡 damageArgTraceSeq 4091(flat=160) 与 4100(flat=0) → 143 / 25 交替
 * 这里把档位落到 localStorage：页面与悬浮窗同源共享；内核由 host 每步按
 * kernelManifest.pageEnv.storage 注入（构建脚本会解析本文件里的常量键并自动纳入）。
 * 本步【只写不读】——读取端在 Step 2 才切过来，保证一次只改一处。 */
const qkBattleGrowthTierStorageKey = "qk.hud.spectator-growth-tiers.v1";
const qkBattleGrowthTierStoreRevision = "20260910-spectator-growth-tier-store-v2";
/* 注意：这里不能用模块级可变绑定（let / 可变对象属性）做缓存。
   内核构建把所有「模块级可变绑定」当成跨步状态（pageEnv.seeds），页面侧不认识就会报
   unknown seed 并让整个接管管线死掉（实测 stepped=0）。每次直读 localStorage。 */
function qkBattleGrowthTierStoreLoad() {
  try {
    if (typeof localStorage === "undefined") return null;
    const raw = localStorage.getItem(qkBattleGrowthTierStorageKey);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch { return null; }
}

function qkBattleGrowthTierStoreGet(battleId, skillId, actorKey) {
  try {
    if (skillId == null || !actorKey) return null;
    const store = qkBattleGrowthTierStoreLoad();
    if (!store) return null;
    const forBattle = store[String(battleId || "")];
    if (!forBattle || typeof forBattle !== "object") return null;
    const forSkill = forBattle[String(skillId)];
    if (!forSkill || typeof forSkill !== "object") return null;
    const entry = forSkill[actorKey];
    if (!entry || typeof entry !== "object") return null;
    const tier = Number(entry.tier);
    if (!Number.isFinite(tier) || tier < 0) return null;
    return { tier: Math.round(tier), round: entry.round ?? null, skillName: entry.skillName ?? null, eventId: entry.eventId ?? null, freezeCount: entry.freezeCount ?? null, computedBaseline: entry.computedBaseline ?? null, lastComputed: entry.lastComputed ?? null };
  } catch { return null; }
}

/* 观战权威档位：本域账本与跨域存储取最大（档位只增不减）。
   没有账本激活、也没有存储记录时返回 null —— 「没激活就完全不算」不变。 */
// Observation reducers read their own counters; calibration is joined at the calculator boundary.
function qkBattleGrowthComputedBag(runtime, skillId, actorKey) {
  return qkBattleGrowthSkillBag(qkBattleGrowthLedger(runtime), skillId);
}

function qkBattleGrowthSpectatorTier(runtime, skillId, actorKey) {
  if (skillId == null || !actorKey) return null;
  if (qkBattleGrowthTrustedOpening(runtime, skillId, actorKey)) return qkBattleGrowthCount(runtime, skillId, actorKey);
  if (qkBattleGrowthSkill({ id: skillId })?.resetAfterUse) return qkBattleGrowthCount(runtime, skillId, actorKey);
  const bag = qkBattleGrowthComputedBag(runtime, skillId, actorKey);
  const ledgerFloor = Math.max(0, Math.round(Number((bag.floor || {})[actorKey]) || 0));
  const ledgerCounted = Math.max(0, Math.round(Number((bag.counts || {})[actorKey]) || 0));
  const stored = qkBattleGrowthTierStoreGet(runtime?.sessionId, skillId, actorKey);
  const storedTier = stored ? Math.max(0, Math.round(stored.tier)) : 0;
  const hasLedgerActivation = !!(bag.activations && bag.activations[actorKey]);
  if (!hasLedgerActivation && !stored) return null;
  return Math.max(ledgerFloor, ledgerCounted, storedTier);
}

function qkBattleGrowthTierStorePut(battleId, skillId, actorKey, tier, round, skillName, activation, lastComputed) {
  try {
    if (typeof localStorage === "undefined") return;
    const battle = String(battleId || "");
    const tierNumber = Number(tier);
    if (!battle || skillId == null || !actorKey) return;
    if (!Number.isFinite(tierNumber) || tierNumber < 0) return;
    const store = qkBattleGrowthTierStoreLoad();
    if (!store) return;
    const nextStore = { ...store };
    const forBattle = nextStore[battle] && typeof nextStore[battle] === "object" ? { ...nextStore[battle] } : {};
    const forSkill = forBattle[String(skillId)] && typeof forBattle[String(skillId)] === "object"
      ? { ...forBattle[String(skillId)] } : {};
    const existing = forSkill[actorKey];
    const existingTier = Number(existing && existing.tier);
    // 档位只增不减：同一局同一技能同一下手方，绝不把已记下的更高档位改小
    if (Number.isFinite(existingTier) && existingTier > tierNumber) return;
    const computedCandidates = [lastComputed, existing?.lastComputed]
      .filter(value => value != null && Number.isFinite(Number(value))).map(Number);
    const storedLastComputed = Number(skillId) === 7110230 && computedCandidates.length
      ? Math.max(...computedCandidates) : lastComputed;
    forSkill[actorKey] = {
      tier: Math.round(tierNumber),
      round: Number.isFinite(Number(round)) ? Number(round) : (existing?.round ?? null),
      skillName: skillName || existing?.skillName || null,
      revision: qkBattleGrowthTierStoreRevision,
      at: Date.now(),
      ...(activation ? { eventId: activation.eventId, freezeCount: activation.freezeCount, computedBaseline: activation.computedBaseline } : {}),
      ...(storedLastComputed != null ? { lastComputed: storedLastComputed } : {})
    };
    forBattle[String(skillId)] = forSkill;
    nextStore[battle] = forBattle;
    localStorage.setItem(qkBattleGrowthTierStorageKey, JSON.stringify(nextStore));
  } catch {}
}

/* 新一局（含重放）开始时清空：否则同一局重放会沿用上一次记下的档位，
   既不符合「本局反推出来的档位」的语义，也会把闪烁掩盖掉、让验证失效。 */
function qkBattleGrowthTierStoreClear(battleId) {
  try {
    if (typeof localStorage === "undefined") return;
    const battle = String(battleId || "");
    if (!battle) return;
    const store = qkBattleGrowthTierStoreLoad();
    if (!store || !store[battle]) return;
    const nextStore = { ...store };
    delete nextStore[battle];
    localStorage.setItem(qkBattleGrowthTierStorageKey, JSON.stringify(nextStore));
  } catch {}
}

function qkBattleGrowthSeedFromReverse(runtime, action, freezeCount) {
  const skill = qkBattleGrowthSkill(action?.skill || action);
  if (!runtime || !skill || !qkBattleGrowthIsSpectator(runtime)) return runtime;
  if (action?.status !== "resolved" || !Number.isFinite(Number(freezeCount)) || Number(freezeCount) < 0) return runtime;
  const positiveDamage = Math.abs(Number(action.damageTotal)) > 0 || (action.impacts || []).some(item => Math.abs(Number(item.damageTotal ?? item.damage)) > 0);
  if (!positiveDamage) return runtime;
  const actorKey = qkBattleGrowthActorKey(runtime, action, action?.side);
  if (!actorKey || qkBattleGrowthActivation(runtime, skill.skillId, actorKey)) return runtime;
  const freeze = Math.max(0, Math.round(Number(freezeCount)));
  const ledger = qkBattleGrowthLedger(runtime);
  const bag = qkBattleGrowthSkillBag(ledger, skill.skillId);
  const observed = qkBattleGrowthObservedCount(runtime, action);
  if (observed == null || freeze < observed) return runtime;
  const currentObserved = Math.max(0, Number(bag.counts[actorKey]) || 0);
  const after = skill.resetAfterUse
    ? (qkBattleGrowthCountAfterReset(runtime, skill.skillId, actorKey, qkBattleGrowthEventId(runtime, action, actorKey)) ?? 0)
    : freeze + Math.max(0, currentObserved - observed, qkBattleGrowthEventFeedsSelf(skill, action) ? 1 : 0);
  let computed = Math.max(0, Number(bag.lastComputed[actorKey] ?? currentObserved) || 0);
  // The seed already includes all observations up to currentObserved.
  if (!skill.resetAfterUse) computed = Math.max(computed, currentObserved);
  if (skill.skillId === 7110230 && typeof dynamicEntryCount === "function") {
    try { computed = Math.max(0, Math.round(Number(dynamicEntryCount(runtime, action.side)) || 0)); } catch {}
  } else if (skill.skillId === 7100260) {
    computed = qkNeedleCountForRefV447(runtime, action.side, action.actor || action);
  } else if (skill.skillId === 7070020) {
    computed = Math.max(0, Math.round(Number(action.skill?.positionChangeCountV296 ?? action.skill?.qkTransmissionPositionChangeCountV296) || 0));
  }
  const eventId = qkBattleGrowthEventId(runtime, action, actorKey);
  const activation = { eventId, round: Number(action.round ?? runtime.turn) || null, freezeCount: freeze, computedBaseline: computed };
  let next = {
    ...runtime,
    qkBattleGrowthLedger: {
      ...ledger,
      sessionId: runtime.sessionId || ledger.sessionId || null,
      bySkill: {
        ...ledger.bySkill,
        [String(skill.skillId)]: {
          counts: { ...bag.counts, [actorKey]: after },
          floor: { ...bag.floor, [actorKey]: skill.resetAfterUse ? 0 : freeze },
          lastComputed: { ...bag.lastComputed, [actorKey]: computed },
          activations: { ...bag.activations, [actorKey]: activation },
          events: [...bag.events, { eventId, actorKey, side: action.side, round: activation.round, skillId: skill.skillId, countAfter: after, reverseSeed: freeze }].slice(-512)
        }
      },
      extra: ledger.extra || {}
    }
  };
  if (skill.skillId === 7050300) {
    const round = Number(runtime.turn ?? action.round);
    const prior = next.qkBattleGrowthLedger.extra.water;
    const water = prior?.round === round ? { ...prior, activeAtRoundStart: { ...prior.activeAtRoundStart }, actedAtRound: { ...prior.actedAtRound } } : { completedTokens: prior?.completedTokens || [], round, activeAtRoundStart: {}, actedAtRound: { round, my: false, enemy: false }, roundSource: "reverse_activation" };
    for (const side of ["my", "enemy"]) {
      const active = runtime.active?.[side];
      const key = qkBattleGrowthActorKey(next, active, side);
      if (key) water.activeAtRoundStart[side] = active || null;
      water.actedAtRound[side] = water.actedAtRound[side] === true || (runtime.evidenceActions || []).some(item => item.side === side && Number(item.round) === round && qkWaterWaveIsActionV446({ ...item, type: item.type || "skill_cast" }));
    }
    next.qkBattleGrowthLedger.extra = { ...next.qkBattleGrowthLedger.extra, water };
  }
  if (skill.skillId === 7150350) next = qkBattleGrowthRebuildTravel(next);
  qkFreezeBattleGrowth(next, { ...action, type: action.type || "skill_cast", qkBattleGrowthCount: freeze }, action);
  /* 反推唯一命中档位 → 落进跨域唯一权威存储（本步只写，不读）。
     这样「本局这个技能这只精灵的档位」不再只活在某个 runtime 对象里。 */
  qkBattleGrowthTierStorePut(
    runtime?.sessionId, skill.skillId, actorKey, after,
    Number(action?.round ?? runtime?.turn) || null, skill.name, activation, computed
  );
  return next;
}

function qkBattleGrowthBonusFromCount(skill, count) {
  const raw = Math.max(0, Math.round(Number(count) || 0));
  const capped = skill.maxSteps != null ? Math.min(raw, Number(skill.maxSteps)) : raw;
  if (skill.kind === qkBattleGrowthKind.MULTIPLIER) {
    const multiplier = Math.pow(Number(skill.multiplier) || 2, capped);
    const base = Number(skill.basePower) || 0;
    return { count: capped, bonus: base * (multiplier - 1), effective: base * multiplier, multiplier };
  }
  const bonus = (Number(skill.step) || 0) * capped;
  return { count: capped, bonus, effective: (Number(skill.basePower) || 0) + bonus, multiplier: 1 };
}

function qkBattleGrowthSamePet(a, b) {
  if (!a || !b) return false;
  if (typeof qkEvidenceSamePetRef === "function") {
    try { if (qkEvidenceSamePetRef(a, b)) return true; } catch {}
  }
  const left = Number(a?.petBattleId ?? a?.battlePetId);
  const right = Number(b?.petBattleId ?? b?.battlePetId);
  if (Number.isFinite(left) && Number.isFinite(right) && left > 0) return left === right;
  return false;
}


function qkBattleGrowthTravelHasTrigger(action) {
  const skillId = Number(action?.skill?.id ?? action?.skillId);
  const sources = [action?.actionKey, action?.sourceActionKey, action?.eventKey, action?.id, ...(action?.sourceEventKeys || [])];
  for (const source of sources) {
    const text = String(source || "");
    const cast = text.match(/(?:^|\|)\s*skill=[^|]*?\((\d+)\)/);
    const effects = text.match(/(?:^|\|)\s*effects=(\d+(?:\/\d+)*)/);
    // 整包效果可能属于应对方：只有主施放者就是本动作时才采用此证据。
    if (cast && Number(cast[1]) === skillId && effects && effects[1].split("/").some(id => Number(id) === 20430100)) return true;
  }
  return false;
}

function qkBattleGrowthRebuildTravel(runtime) {
  const actions = Array.isArray(runtime?.evidenceActions) ? runtime.evidenceActions : [];
  const byRound = new Map();
  const seen = new Set();
  for (const [index, action] of actions.entries()) {
    const side = action?.side;
    const round = Number(action?.round);
    const skill = action?.skill || action;
    if ((side !== "my" && side !== "enemy") || !Number.isFinite(round) || action?.segmentEvidence) continue;
    if (!(skill?.id || skill?.name || action?.skillId || action?.skillName)) continue;
    const eventKey = String(
      action?.actionKey ?? action?.sourceActionKey ?? action?.eventKey ?? action?.sourceActionId ?? action?.id ??
      [side, round, skill?.id ?? action?.skillId, index].join("|")
    ).replace(/-segment-\d+$/i, "");
    const seenKey = side + "|" + round + "|" + eventKey;
    if (seen.has(seenKey)) continue;
    seen.add(seenKey);
    const isCounterVersion = qkBattleGrowthIsCounterSkill(action);
    if (skill?.isCounter === true && !isCounterVersion) continue;
    const rec = {
      action,
      index,
      eventKey,
      actorKey: qkBattleGrowthActorKey(runtime, action, side),
      isCounterVersion,
      skillId: Number(skill?.id ?? action?.skillId) || null,
      skillName: skill?.name ?? action?.skillName ?? null
    };
    const bucket = byRound.get(round) || { my: [], enemy: [] };
    bucket[side].push(rec);
    byRound.set(round, bucket);
  }
  const counts = {};
  const events = [];
  for (const round of [...byRound.keys()].sort((a, b) => a - b)) {
    const bucket = byRound.get(round);
    const pick = list => list.find(item => item.isCounterVersion) || list[0] || null;
    const mine = pick(bucket.my);
    const enemy = pick(bucket.enemy);
    let winner = null;
    if (!mine || !enemy) {
      const only = mine || enemy;
      // 对方休息、未能出手或被击倒时，不能仅凭少一条动作就判断先手。
      // 只接受成功应对或属于本使用者的原始远行成长触发。
      if (only?.actorKey && (only.isCounterVersion || qkBattleGrowthTravelHasTrigger(only.action))) winner = only;
    } else if (!mine.actorKey || !enemy.actorKey) continue;
    else if (mine.isCounterVersion && !enemy.isCounterVersion) winner = mine;
    else if (enemy.isCounterVersion && !mine.isCounterVersion) winner = enemy;
    else if (mine.isCounterVersion && enemy.isCounterVersion) winner = null;
    else if (mine.index < enemy.index) winner = mine;
    else if (enemy.index < mine.index) winner = enemy;
    if (!winner) continue;
    const eventId = [runtime?.sessionId || "battle", round, mine?.eventKey || "no_my_action", enemy?.eventKey || "no_enemy_action", winner.actorKey, winner.isCounterVersion ? "counter_absolute" : !mine || !enemy ? "protocol_travel_trigger" : "protocol_order"].join("|");
    const next = Math.max(0, Math.round(Number(counts[winner.actorKey]) || 0)) + 1;
    counts[winner.actorKey] = next;
    events.push({
      eventId,
      round,
      winnerActorKey: winner.actorKey,
      winnerSide: winner.action?.side,
      countAfter: next
    });
  }
  const ledger = qkBattleGrowthLedger(runtime);
  return {
    ...runtime,
    qkBattleGrowthLedger: {
      ...ledger,
      bySkill: {
        ...ledger.bySkill,
        "7150350": qkBattleGrowthProtectComputed(qkBattleGrowthSkillBag(ledger, 7150350), counts, events)
      },
      extra: ledger.extra || qkBattleGrowthEmptyLedger(runtime).extra
    }
  };
}

function qkBattleGrowthTravelCount(runtime, event, beforeCurrentRound) {
  const actorKey = qkBattleGrowthActorKey(runtime, event, event?.side);
  if (!actorKey) return 0;
  const bag = qkBattleGrowthSkillBag(qkBattleGrowthLedger(runtime), 7150350);
  if (qkBattleGrowthIsSpectator(runtime)) {
    const current = qkBattleGrowthCount(runtime, 7150350, actorKey);
    const round = Number(event?.round);
    const thisRound = beforeCurrentRound && Number.isFinite(round) ? (bag.events || []).filter(item => item.winnerActorKey === actorKey && Number(item.round) >= round).length : 0;
    return Math.max(0, current - thisRound);
  }
  if (beforeCurrentRound) {
    const round = Number(event?.round);
    if (Number.isFinite(round)) {
      return (bag.events || []).filter(item => item?.winnerActorKey === actorKey && Number(item?.round) < round).length;
    }
  }
  return qkBattleGrowthCount(runtime, 7150350, actorKey);
}

function qkBattleGrowthNeedleCount(runtime, side, actor, throughAction) {
  const throughRound = Number(throughAction?.round ?? runtime?.turn);
  const rounds = new Map();
  const actorRef = actor?.actor || actor || runtime?.active?.[side] || {};
  const mark = (round, attack) => {
    if (!Number.isFinite(round) || round <= 0) return;
    if (Number.isFinite(throughRound) && round >= throughRound) return;
    const rec = rounds.get(round) || { attack: false, seen: false };
    rec.seen = true;
    rec.attack = rec.attack || !!attack;
    rounds.set(round, rec);
  };
  for (const action of runtime?.evidenceActions || []) {
    if (throughAction && (action?.actionKey && throughAction?.actionKey && action.actionKey === throughAction.actionKey)) break;
    if (action?.side !== side) continue;
    const actionActor = action?.actor || action;
    if (actorRef && (actorRef.petBattleId != null || actorRef.battlePetId != null) && !qkBattleGrowthSamePet(actionActor, actorRef)) continue;
    mark(Number(action?.round), qkBattleGrowthIsAttack(action));
  }
  return [...rounds.values()].filter(item => item.seen && !item.attack).length;
}

function qkBattleGrowthRefreshEntries(runtime, event) {
  const side = event?.side;
  if (side !== "my" && side !== "enemy") {
    let next = runtime;
    for (const activeSide of ["my", "enemy"]) {
      next = qkBattleGrowthRefreshEntries(next, { ...event, side: activeSide });
    }
    return next;
  }
  const actor = runtime?.active?.[side] || event;
  const actorKey = qkBattleGrowthActorKey(runtime, actor, side);
  if (!actorKey) return runtime;
  let count = 0;
  if (typeof dynamicEntryCount === "function") {
    try { count = Math.max(0, Math.round(Number(dynamicEntryCount(runtime, side)) || 0)); } catch { count = 0; }
  } else {
    count = qkBattleGrowthCount(runtime, 7110230, actorKey);
    const kind = String(event?.kind || event?.type || "");
    if (kind === "switch" || kind === "active_changed" || kind === "battle_start") {
      if (count <= 0) count = 1;
      else if (kind !== "battle_start") count += 1;
    } else if (count <= 0 && runtime?.active?.[side]) {
      count = 1;
    }
  }
  return qkBattleGrowthCommitComputed(runtime, 7110230, actorKey, count, event);
}

// qkWaterWaveRoundEndV446: 判断某侧精灵在回合结算时是否"仍在场上"。
// 判据（任一不满足即视为不在场，本回合不计层）：
//   · 当前 active 必须仍是同一只（已被替换 → 不在场）
//   · deadPets 里没有它（力竭 → 不在场）；deadPets 格式为 "side:petBattleId" -> true
function qkWaterWaveStillOnFieldV446(runtime, side, actorKey) {
  if (!actorKey) return false;
  const current = runtime?.active?.[side];
  const currentKey = qkBattleGrowthActorKey(runtime, current || {}, side);
  if (!currentKey || currentKey !== actorKey) return false;
  const dead = runtime?.deadPets;
  if (!dead || typeof dead !== "object") return true;
  if (dead[actorKey] === true) return false;
  const petId = String(actorKey).split(":").pop();
  if (petId && dead[side + ":" + petId] === true) return false;
  return true;
}

// qkWaterWaveRoundEndV446: 该事件是否算"这一方本回合的一次行动"。
// 换人 / 出手 / 使用技能都算；纯状态快照与心跳不算。
// （实测第 3 回合敌方没有 skill_cast，但它换了人、放了 buff，仍属"已行动"。）
function qkWaterWaveIsActionV446(event) {
  const type = String(event?.type || event?.kind || "");
  const rawKind = String(event?.rawKind || "");
  if (type === "skill_cast" || type === "active_changed") return true;
  if (type === "buff_change" && rawKind === "buff_change") return true;
  return false;
}

function qkBattleGrowthAdvanceWater(runtime, event, previous = runtime) {
  const ledger = qkBattleGrowthLedger(runtime);
  const activeRefs = () => Object.fromEntries(["my", "enemy"].map(side => [side, runtime.active?.[side] || null]));
  const extra = { ...(ledger.extra || {}) };
  const water = { ...(extra.water || { completedTokens: [], round: null, activeAtRoundStart: {}, roundSource: null }) };
  let countsRuntime = runtime;
  if (event?.type === "battle_start") {
    extra.water = {
      completedTokens: [],
      round: Number(runtime?.turn) || 1,
      activeAtRoundStart: activeRefs(),
      roundSource: "battle_start"
    };
    return { ...runtime, qkBattleGrowthLedger: { ...ledger, extra: { ...extra, water: extra.water } } };
  }
  const previousRound = Number(water.round);
  // qkWaterWaveRoundEndV446: 计数口径 =「回合结束且精灵仍在场」。
  //   · 回合结束 = 敌我双方都已完成本回合行动
  //   · 仍在场   = 上一回合末该侧 active，且当时未进入 deadPets；不要求回合开场就在场
  // 注意：不能用 runtime.currentTurn（它只在 round_start 重置，而生产者从不产生该事件，
  // 一旦置位就永不复位）。因此这里在账本内自行记录"本回合哪几方已行动"。
  const nextRound = Number(event?.round ?? event?.turn);
  // Ignore stale rounds without rewinding the water ledger or replaying completed rounds.
  if (Number.isFinite(nextRound) && Number.isFinite(previousRound) && nextRound < previousRound) return runtime;
  const roundAdvanced = Number.isFinite(nextRound) && Number.isFinite(previousRound) && nextRound > previousRound;
  if (roundAdvanced) {
    const acted = water.actedAtRound || { round: previousRound, my: false, enemy: false };
    // 只有当"双方都行动过"才认定上一回合完整结束
    if (acted.my === true && acted.enemy === true) {
      const tokens = [...(water.completedTokens || [])];
      for (const side of ["my", "enemy"]) {
        // runtime already includes the incoming event. The previous state owns
        // the completed round, including late switches and late opening identities.
        const endState = previous || runtime;
        const active = endState.active?.[side];
        if (!active) continue;
        const actorKey = qkBattleGrowthActorKey(endState, active, side);
        if (!actorKey) continue;
        if (!qkWaterWaveStillOnFieldV446(endState, side, actorKey)) continue;
        const token = side + ":" + previousRound + ":" + actorKey;
        if (tokens.includes(token)) continue;
        tokens.push(token);
        countsRuntime = qkBattleGrowthBump(countsRuntime, 7050300, actorKey, event);
      }
      water.completedTokens = tokens.slice(-256);
    }
  }
  if (Number.isFinite(nextRound)) {
    // 回合推进时，本回合行动记录清空重来；否则累积本回合的双方行动
    const sameRound = Number.isFinite(previousRound) && nextRound === previousRound;
    const prev = sameRound ? (water.actedAtRound || {}) : {};
    const side = event?.side;
    const acted = {
      round: nextRound,
      my: prev.my === true || (side === "my" && qkWaterWaveIsActionV446(event)),
      enemy: prev.enemy === true || (side === "enemy" && qkWaterWaveIsActionV446(event))
    };
    water.actedAtRound = acted;
    water.activeAtRoundStart = sameRound
      ? (water.activeAtRoundStart || { my: null, enemy: null })
      : activeRefs();
    water.round = nextRound;
    water.roundSource = String(event?.type || event?.kind || "unknown");
  }
  extra.water = water;
  const nextLedger = qkBattleGrowthLedger(countsRuntime);
  return {
    ...countsRuntime,
    qkBattleGrowthLedger: { ...nextLedger, extra: { ...(nextLedger.extra || {}), water } }
  };
}

// qkNeedleOfficialRuleV447: 绵里藏针判定"是否攻击技能"。
// 官方描述（authority/skill.json 7100260）：
//   "造成魔伤，若自己上回合未使用攻击技能，本技能威力永久+20。"
// 判据优先级：
//   1) 技能表 Skill_Type —— 实测 7100260/7020970/7060180/7060200/7060130/7090360/7100150 为 1（攻击），
//      7030290/7100170 为 2（非攻击），7100100/7000010 无该字段（蓄力/聚能，非攻击）。
//   2) 回退 qkProgressiveEventIsAttack 的 category 判定。
// 注意：正常换人不是技能，但同样属于"该回合未使用攻击技能"，由 qkNeedleRoundActionV447 统一登记。
function qkNeedleIsAttackSkillV447(event) {
  const id = Number(event?.skillId ?? event?.skill?.id ?? 0);
  try {
    if (typeof jv === "function" && Number.isFinite(id) && id > 0) {
      const entry = jv(id);
      if (entry) {
        const t = entry.Skill_Type ?? entry.skillType ?? entry.skill_type;
        if (t != null && String(t) !== "") return Number(t) === 1;
      }
    }
  } catch {}
  // 回退 1：事件自带 category（技能表查不到时，例如测试沙箱）
  const category = String(event?.category ?? event?.skill?.category ?? event?.move_category ?? "");
  if (category) return category === "Physical Attack" || category === "Magic Attack";
  // 回退 2：运行时 category 判定
  if (typeof qkProgressiveEventIsAttack === "function") {
    try { return qkProgressiveEventIsAttack(event) === true; } catch {}
  }
  return false;
}

// qkNeedleOfficialRuleV447: 绵里藏针按官方描述在「使用该技能那一刻」判定一次。
//   技能表原文（authority/skill.json 7100260）：
//     "造成魔伤，若自己上回合未使用攻击技能，本技能威力永久+20。"
//   因此：每次 skill_cast 绵里藏针时，检查【该使用者】在【上一回合】有没有用过攻击技能；
//   没有 → 本次 +1 层（每层 +20，永久累积，绑定使用者 side:petBattleId，与水波术一致）。
//   「上一回合」= 该使用者上一次行动所在的回合（中间被换下时按它自己的行动序列对齐，
//   不强行用 round-1，避免换人期间误判）。
//   「未使用攻击技能」包含三类：①使用了非攻击技能（移花接木/蓄力/聚能等）；
//   ②正常换人（换人不是技能，但同样意味着该回合没攻击）；③该回合无任何行动记录。
// Preserve replacement phases until all identities in the ready packet are applied.
function qkBattleGrowthRoundPhaseEvents(row, events) {
  if (String(row?.opencode || "").toUpperCase() !== "0X131A" && row?.meaning !== "ZoneBattleRoundStartNotify") return events;
  const content = row?.content;
  const phase = Number(content?.state_type), round = Number(content?.state_info?.round);
  if ((phase !== 0 && phase !== 1) || !Number.isFinite(round)) return events;
  const decorated = events.map(event => ({ ...event, qkNeedleRoundPhase: phase, qkNeedlePhaseRound: round }));
  decorated.push(Ke(row, "battle_round_phase", "my", {
    id: `rkpp-${Ra(row)}-needle-round-phase`, round,
    qkNeedleRoundPhase: phase, qkNeedlePhaseRound: round,
    visible: false, text: "", confidence: 1
  }));
  return decorated;
}

function qkBattleGrowthAdvanceNeedle(runtime, event) {
  const ledger = qkBattleGrowthLedger(runtime);
  const type = String(event?.type || "");
  const isCast = type === "skill_cast";
  const isSwitch = type === "active_changed" || type === "switch";
  const side = event?.side;
  if (side !== "my" && side !== "enemy") return runtime;

  /* qkNeedleRoundMonotonicV451: 回合号只认事件自带的 round。
     原来写的是 `Number(event?.round ?? runtime?.turn)`：事件流里有一批事件**不带 round**
     （original_skills_snapshot、部分 buff_change），只能退回 runtime.turn，而 runtime.turn
     与真实回合并不同步（实测 battle-1592018589920002181：R4 起点 23:54:42.6，
     运行时 turn 到 23:54:46 才变成 4）。用它会同时造成两种错：
       · 回合号被**往回拽** → "上一回合"重复指向同一回合，中间符合条件的回合永远补不上；
       · 回合号**超前** → 把还没发生的回合也结算掉（离线实测：R2 就多算一档）。
     因此：只有带 round 的事件才能推进回合；不带 round 的事件只登记在场者/攻击标记。 */
  const eventRound = Number(event?.round);
  const hasEventRound = Number.isFinite(eventRound);
  if (!hasEventRound) {
    const prevOnly = Number(qkBattleGrowthLedger(runtime).extra?.needle?.round);
    if (!Number.isFinite(prevOnly)) return runtime;
  }

  const extra = { ...(ledger.extra || {}) };
  const needle = { ...(extra.needle || {}) };
  const prevRound = Number(needle.round);
  const onField = { ...(needle.onField || {}) };
  const attackedAt = { ...(needle.attackedAt || {}) };
  const counted = { ...(needle.counted || {}) };
  let next = runtime;
  let pendingRound = Number(needle.pendingRound) || 0;
  const phaseRound = Number(event?.qkNeedlePhaseRound);
  if (event?.qkNeedleRoundPhase === 0 && Number.isFinite(phaseRound) && (!Number.isFinite(prevRound) || phaseRound > prevRound)) {
    pendingRound = Math.max(pendingRound, phaseRound);
  }
  if (type === "battle_round_phase" && event?.qkNeedleRoundPhase === 1 && phaseRound >= pendingRound) pendingRound = 0;
  const waitingForReplacement = pendingRound > 0;


  // qkNeedleNonAttackRoundV450: 官方规则「造成魔伤，若自己上回合未使用攻击技能，本技能威力永久+20。」
  // 计数口径 = 每一个"已结束的完整回合"里，该回合**结束时仍在场**的精灵若**未使用攻击技能**，
  //            则该精灵 +1 层（每层 +20，绑定使用者 side:petBattleId）。
  //   · 用回合号推进判定"回合已结束"（生产者从不产生 round_start，实测五局 0 次）。
  //   · 用上一回合结束时的在场者 onField：被换下场的精灵该回合不计。
  //     实测第 7 回合伊兰亚龙使用移花接木后离场 → 不计；第 9 回合换回场上且未行动 → 计入。
  //   · 第 1 回合之前不存在"上一回合" → 不计数（实测第 1 回合 0 层）。
  // qkNeedleSettleWholeGapV451: 一次把 [prevRound, eventRound) 之间**所有**未结算的回合都结算掉。
  //   原来只结算 prevRound 这一个：一旦回合号跳号，中间那些符合条件的回合就永久丢失，
  //   而且 counted 只记 token，漏掉的回合之后也不会被补回来。
  //   前提是 eventRound 可靠 —— 所以这里只由带 round 的事件触发。
  if (!waitingForReplacement && hasEventRound && Number.isFinite(prevRound) && eventRound > prevRound) {
    for (let r = prevRound; r < eventRound; r += 1) {
      for (const s of ["my", "enemy"]) {
        const key = onField[s];
        if (!key) continue;
        const token = key + ":" + r;
        if (counted[token] === true) continue;
        if (attackedAt[token] === true) continue;
        counted[token] = true;
        next = qkBattleGrowthBump(next, 7100260, key, { ...event, actionKey: qkBattleGrowthEventId(runtime, event, key) + "|needle|" + r });
      }
    }
  }

  // 登记本回合状态：当前在场者，以及"本回合是否使用过攻击技能"。
  // attackedAt 只按事件自带的 round 登记（攻击技能出手事件实测都带 round）；
  // 没有 round 的事件不登记，避免用不同步的运行时回合号把别的回合标成"已攻击"。
  const actorKey = qkBattleGrowthActorKey(runtime, event, side);
  if (actorKey) {
    if (isSwitch || isCast) onField[side] = actorKey;
    if (isCast && hasEventRound && qkNeedleIsAttackSkillV447(event)) attackedAt[actorKey + ":" + eventRound] = true;
  }

  const settledRound = hasEventRound && !waitingForReplacement
    ? (Number.isFinite(prevRound) ? Math.max(prevRound, eventRound) : eventRound)
    : prevRound;
  const nextLedger = qkBattleGrowthLedger(next);
  extra.needle = { ...needle, onField, attackedAt, counted, round: settledRound, pendingRound };
  return { ...next, qkBattleGrowthLedger: { ...nextLedger, extra: { ...(nextLedger.extra || {}), ...extra } } };
}

function qkBattleGrowthFeedCast(runtime, event) {
  if (event?.type !== "skill_cast" || qkBattleGrowthSkipEvent(event) || (event.side !== "my" && event.side !== "enemy")) return runtime;
  if (!qkBattleGrowthObservedValid(event)) return runtime;
  const actorKey = qkBattleGrowthActorKey(runtime, event, event.side);
  if (!actorKey) return runtime;
  const growth = qkBattleGrowthSkill(event);
  let next = runtime;
  if (growth?.resetAfterUse) {
    next = qkBattleGrowthPutCount(next, growth.skillId, actorKey, 0, event, true);
  } else if (qkBattleGrowthIsFireType(event)) {
    next = qkBattleGrowthBump(next, 7040690, actorKey, event);
  }
  if (qkBattleGrowthIsFireType(event) && growth?.skillId !== 7040250) {
    next = qkBattleGrowthBump(next, 7040250, actorKey, event);
  }
  if (qkBattleGrowthIsGrassType(event) && growth?.skillId !== 7030210) {
    next = qkBattleGrowthBump(next, 7030210, actorKey, event);
  }
  // 过曝 7060120：非光系技能 +1。过曝自己是光系，天然被排除，故「施放当次不计入」
  // 无需额外判断；聚能(7000010) 按用户指定单独排除，其余判据不变。
  if (!qkBattleGrowthIsLightType(event) && growth?.skillId !== 7060120 && !qkBattleGrowthIsOverexposeExcluded(event)) {
    next = qkBattleGrowthBump(next, 7060120, actorKey, event);
  }
  if (growth?.skillId === 7040200) {
    next = qkBattleGrowthBump(next, 7040200, actorKey, event);
  }
  if (qkBattleGrowthIsCounterSkill(event)) {
    next = qkBattleGrowthBump(next, 7020570, actorKey, event);
  }
  return next;
}

function qkBattleGrowthFeedGear(runtime, event) {
  if (event?.type === "my_skill_positions_snapshot" && Array.isArray(event.originalSkills)) {
    const gear = event.originalSkills.find(item => qkBattleGrowthSkill(item)?.skillId === 7070020);
    if (!gear) return runtime;
    const count = Math.max(0, Math.round(Number(gear.transmissionConfirmedChangeCountV296 ?? gear.positionChangeCountV296 ?? gear.qkTransmissionPositionChangeCountV296) || 0));
    const actorKey = qkBattleGrowthActorKey(runtime, runtime?.active?.my || event, "my");
    if (!actorKey) return runtime;
    return qkBattleGrowthIsSpectator(runtime) ? qkBattleGrowthCommitComputed(runtime, 7070020, actorKey, count, event) : qkBattleGrowthPutCount(runtime, 7070020, actorKey, count, event, true);
  }
  if (event?.type === "skill_cast" && qkBattleGrowthSkill(event)?.skillId === 7070020 && event.side === "my") {
    const fromMove = Math.max(0, Math.round(Number(
      event?.qkTransmissionPositionChangeCountV296 ??
      event?.positionChangeCountV296 ??
      event?.skill?.qkTransmissionPositionChangeCountV296 ??
      event?.skill?.positionChangeCountV296
    ) || 0));
    const actorKey = qkBattleGrowthActorKey(runtime, event, "my");
    if (!actorKey) return runtime;
    const current = qkBattleGrowthCount(runtime, 7070020, actorKey);
    if (qkBattleGrowthIsSpectator(runtime)) return qkBattleGrowthCommitComputed(runtime, 7070020, actorKey, fromMove, event);
    if (fromMove > current) return qkBattleGrowthPutCount(runtime, 7070020, actorKey, fromMove, event, true);
  }
  return runtime;
}

function qkReducerBattleGrowth(previous, event, runtime) {
  if (!runtime) return runtime;
  if (event?.type === "battle_start") {
    let next = { ...runtime, qkBattleGrowthLedger: qkBattleGrowthEmptyLedger(runtime) };
    qkBattleGrowthTierStoreClear(runtime?.sessionId);
    next = qkBattleGrowthAdvanceWater(next, event);
    next = qkBattleGrowthRefreshEntries(next, { type: "battle_start", side: "my" });
    next = qkBattleGrowthRefreshEntries(next, { type: "battle_start", side: "enemy" });
    return next;
  }
  // 两种模式只推进当前模式的一份账本，身份切换时不接用旧模式的计数。
  let next = { ...runtime, qkBattleGrowthLedger: { ...qkBattleGrowthLedger(runtime), countingMode: qkBattleGrowthIsSpectator(runtime) ? "spectator" : "battle" } };
  next = qkBattleGrowthAdvanceWater(next, event, previous);
  next = qkBattleGrowthAdvanceNeedle(next, event);
  next = qkBattleGrowthFeedCast(next, event);
  next = qkBattleGrowthFeedGear(next, event);
  if (event?.type === "skill_cast" && !qkBattleGrowthSkipEvent(event)) {
    next = qkBattleGrowthRebuildTravel(next);
  }
  const kind = String(event?.kind || event?.type || "");
  if (kind === "switch" || kind === "active_changed" || event?.type === "skill_cast" || event?.type === "round_start") {
    next = qkBattleGrowthRefreshEntries(next, event);
  }
  return next;
}


function qkBattleGrowthLiveCount(runtime, side, move, actor) {
  const skill = qkBattleGrowthSkill(move);
  if (!skill) return null;
  if (skill.skillId === 7070020 && side === "enemy") return null;
  const ref = actor || runtime?.active?.[side] || { side };
  const actorKey = qkBattleGrowthActorKey(runtime, { ...ref, side }, side);
  if (qkBattleGrowthIsSpectator(runtime)) {
    // 首次出手前用已观测次数预览；首次伤害确认后继续使用校准档位。
    // 此处只读取计数，不激活、不冻结动作，也不推进另一套实战账本。
    const spectatorActivated = !!actorKey && qkBattleGrowthActivation(runtime, skill.skillId, actorKey);
    if (spectatorActivated) {
      return qkBattleGrowthSpectatorTier(runtime, skill.skillId, actorKey);
    }
  }
  if (skill.skillId === 7150350) return qkBattleGrowthTravelCount(runtime, { ...ref, side }, false);
  if (skill.skillId === 7100260) return qkNeedleCountForRefV447(runtime, side, ref);
  if (skill.skillId === 7070020) {
    const fromLedger = qkBattleGrowthCount(runtime, skill.skillId, actorKey);
    const fromMove = Math.max(0, Math.round(Number(
      move?.qkTransmissionPositionChangeCountV296 ?? move?.positionChangeCountV296 ?? 0
    ) || 0));
    return Math.max(fromLedger, fromMove);
  }
  if (skill.skillId === 7110230 && typeof dynamicEntryCount === "function") {
    try { return Math.max(0, Math.round(Number(dynamicEntryCount(runtime, side)) || 0)); } catch {}
  }
  return qkBattleGrowthCount(runtime, skill.skillId, actorKey);
}

function qkBattleGrowthSnapshotCount(action) {
  const skill = qkBattleGrowthSkill(action?.skill || action);
  const fields = [
    action?.qkBattleGrowthCount,
    action?.skill?.qkBattleGrowthCount,
    action?.qkBattleGrowth?.count,
    action?.skill?.qkBattleGrowth?.count
  ];
  if (skill?.skillId === 7040250) {
    fields.push(action?.qkMountainFireOtherFireCountV374, action?.qkMountainFireV374?.otherFireCount, action?.skill?.qkMountainFireOtherFireCountV374);
  }
  if (skill?.skillId === 7020570) {
    fields.push(action?.qkEnergyBladeCounterCountV379, action?.qkEnergyBladeV379?.counterCount, action?.skill?.qkEnergyBladeCounterCountV379);
  }
  if (skill?.skillId === 7150350) {
    fields.push(action?.qkTravelFirstActionCountV383, action?.qkTravelV383?.firstActionCount, action?.skill?.qkTravelFirstActionCountV383);
  }
  if (skill?.skillId === 7050300) {
    fields.push(action?.qkWaterWaveRoundCount, action?.qkWaterWaveRound?.count, action?.skill?.qkWaterWaveRoundCount);
  }
  for (const value of fields) {
    if (value == null) continue;
    const count = Number(value);
    if (Number.isFinite(count) && count >= 0) return Math.round(count);
  }
  return null;
}


function qkBattleGrowthEvidenceCount(action, runtime) {
  // Historical evidence belongs to its own cast-time tier. The live ledger is
  // already advanced when inference runs and must not override that snapshot.
  // Live/next-cast previews have their separate qkBattleGrowthLiveCount reader.
  const frozen = qkBattleGrowthSnapshotCount(action);
  const resetSkill = qkBattleGrowthSkill(action?.skill || action);
  if (resetSkill?.resetAfterUse) {
    if (qkBattleGrowthIsSpectator(runtime) && !qkBattleGrowthActivation(runtime, resetSkill.skillId, qkBattleGrowthActorKey(runtime, action, action?.side))) return frozen;
    if (frozen != null) return frozen;
    const actorKey = qkBattleGrowthActorKey(runtime, action, action?.side);
    const eventId = qkBattleGrowthEventId(runtime, action, actorKey);
    const activation = qkBattleGrowthActivation(runtime, resetSkill.skillId, actorKey);
    if (activation?.eventId === eventId) return activation.freezeCount;
    const event = qkBattleGrowthSkillBag(qkBattleGrowthLedger(runtime), resetSkill.skillId).events.find(item => item.eventId === eventId && item.actorKey === actorKey);
    return event?.countBefore ?? null;
  }
  if (qkBattleGrowthIsSpectator(runtime)) {
    if (frozen != null) return frozen; // Zero is a valid first-cast snapshot.
    const skill = qkBattleGrowthSkill(action?.skill || action);
    const actorKey = qkBattleGrowthActorKey(runtime, action, action?.side);
    const eventId = action?.actionKey ?? action?.eventKey ?? action?.id;
    if (!skill || !actorKey || eventId == null || !String(eventId).trim()) return null;
    const activation = qkBattleGrowthLedger(runtime).bySkill?.[String(skill.skillId)]?.activations?.[actorKey]
      || qkBattleGrowthTierStoreGet(runtime?.sessionId, skill.skillId, actorKey);
    // A cross-domain clone may lack fields, but only the exact calibration
    // event can recover its tier from activation. Another cast stays unknown;
    // neither the latest ledger nor a fixed -1 is a historical observation.
    // Activation() can substitute a current stored tier for absent freezeCount;
    // history must inspect the original field, never that live compatibility fallback.
    if (activation?.eventId === String(eventId)) {
      const value = activation.freezeCount;
      if (typeof value !== "number" && !(typeof value === "string" && value.trim())) return null;
      const count = Number(value);
      if (Number.isInteger(count) && count >= 0) return count;
    }
    return null;
  }
  if (frozen != null) {
    return frozen;
  }
  const skill = qkBattleGrowthSkill(action?.skill || action);
  if (!skill) {
    return 0;
  }
  const side = action?.side;
  if (skill.skillId === 7150350) {
    const value = qkBattleGrowthTravelCount(runtime, action, true);
    return value;
  }
  if (skill.skillId === 7100260) {
    const value = qkNeedleCountForRefV447(runtime, side, action?.actor || action);
    return value;
  }
  const value = qkBattleGrowthLiveCount(runtime, side, action?.skill || action, action?.actor || action) || 0;
  return value;
}

// 观战出手前观测到的下限；只用于恢复候选，不是已确定的HUD档位。
function qkBattleGrowthObservedCount(runtime, event, countRuntime) {
  const skill = qkBattleGrowthSkill(event);
  if (!skill || !qkBattleGrowthIsSpectator(runtime)) return null;
  const frozen = event?.qkBattleGrowthObservedCount ?? event?.skill?.qkBattleGrowthObservedCount;
  if (frozen != null && Number.isFinite(Number(frozen))) return Math.max(0, Math.round(Number(frozen)));
  const source = countRuntime || runtime;
  const actorKey = qkBattleGrowthActorKey(source, event, event?.side);
  if (!actorKey) return 0;
  const bag = qkBattleGrowthSkillBag(qkBattleGrowthLedger(source), skill.skillId);
  const eventId = qkBattleGrowthEventId(source, event, actorKey);
  const recorded = bag.events.find(item => item.eventId === eventId && item.actorKey === actorKey);
  // Round-based growth is settled before this cast; that completed round belongs to its current power.
  if (skill.skillId === 7050300 || skill.skillId === 7100260) return qkBattleGrowthCount(source, skill.skillId, actorKey, event);
  if (recorded?.countBefore != null) return Math.max(0, Math.round(Number(recorded.countBefore) || 0));
  if (skill.skillId === 7150350) return qkBattleGrowthTravelCount(source, event, true);
  if (skill.skillId === 7110230 && typeof dynamicEntryCount === "function") {
    try { return Math.max(0, Math.round(Number(dynamicEntryCount(source, event.side)) || 0)); } catch {}
  }
  if (skill.skillId === 7070020 && event.side === "my") {
    const fromMove = Number(event?.qkTransmissionPositionChangeCountV296 ?? event?.positionChangeCountV296 ?? event?.skill?.qkTransmissionPositionChangeCountV296 ?? event?.skill?.positionChangeCountV296);
    if (Number.isFinite(fromMove)) return Math.max(qkBattleGrowthCount(source, skill.skillId, actorKey, event), Math.max(0, Math.round(fromMove)));
  }
  return qkBattleGrowthCount(source, skill.skillId, actorKey, event);
}

function qkBattleGrowthDecorateEvent(runtime, event) {
  if (!event || event?.type !== "skill_cast" || qkBattleGrowthSkipEvent(event)) return event;
  const skill = qkBattleGrowthSkill(event);
  if (!skill) return event;
  const actorKey = qkBattleGrowthActorKey(runtime, event, event.side);
  let countRuntime = runtime;
  if (qkBattleGrowthIsSpectator(runtime)) {
    if (skill.skillId === 7050300) countRuntime = qkBattleGrowthAdvanceWater(runtime, event);
    else if (skill.skillId === 7100260) countRuntime = qkBattleGrowthAdvanceNeedle(runtime, event);
  } else if (skill.skillId === 7050300) {
    // Decorate precedes reducers in both modes; preview old-round growth only.
    countRuntime = qkBattleGrowthAdvanceWater(runtime, event);
  } else if (skill.skillId === 7100260) {
    // qkNeedleDecorateOrderV448: 实战模式下 runtime 的调用顺序是
    //   decorate（本函数，算显示威力）→ reducer（累加层数）
    // 而绵里藏针是"使用这一刻就 +20"，必须先把本次的层加上再读，否则第一次使用
    // 会显示基础威力 60（实测第一回合显示 162-231 ≈ 60 威，而真实伤害 241 对应 80 威）。
    // 这里只推进读取用的副本 countRuntime，不修改传入的 runtime，
    // 真正的层数仍由后续 qkReducerBattleGrowth → qkBattleGrowthAdvanceNeedle 落账。
    countRuntime = qkBattleGrowthAdvanceNeedle(runtime, event);
  }
  if (qkBattleGrowthIsSpectator(runtime)) {
    const observed = qkBattleGrowthObservedCount(runtime, event, countRuntime);
    event = { ...event, qkBattleGrowthObservedCount: observed, skill: { ...(event.skill || { id: skill.skillId, name: skill.name }), qkBattleGrowthObservedCount: observed } };
  }
  if (!qkBattleGrowthEnabled(runtime, skill.skillId, actorKey)) return event;
  let count;
  if (skill.skillId === 7150350) count = qkBattleGrowthTravelCount(runtime, event, true);
  else if (skill.skillId === 7100260) count = qkNeedleCountForRefV447(countRuntime, event.side, event);
  else count = qkBattleGrowthLiveCount(countRuntime, event.side, event, event);
  if (count == null) return event;
  const math = qkBattleGrowthBonusFromCount(skill, count);
  const decorated = {
    ...event,
    qkBattleGrowthCount: math.count,
    qkBattleGrowthBonus: math.bonus,
    qkBattleGrowthEffectivePower: math.effective,
    qkBattleGrowthRevision: qkBattleGrowthRevision
  };
  if (skill.skillId === 7040250) {
    decorated.qkMountainFireOtherFireCountV374 = math.count;
    decorated.qkMountainFirePowerMultiplierV374 = math.multiplier;
    decorated.qkMountainFireEffectivePowerV374 = math.effective;
  }
  if (skill.skillId === 7020570) {
    decorated.qkEnergyBladeCounterCountV379 = math.count;
    decorated.qkEnergyBladePowerBonusV379 = math.bonus;
    decorated.qkEnergyBladeEffectivePowerV379 = math.effective;
  }
  if (skill.skillId === 7150350) {
    decorated.qkTravelFirstActionCountV383 = math.count;
    decorated.qkTravelPowerBonusV383 = math.bonus;
    decorated.qkTravelEffectivePowerV383 = math.effective;
  }
  if (skill.skillId === 7050300) {
    decorated.qkWaterWaveRoundCount = math.count;
    decorated.qkWaterWaveRound = { revision: qkBattleGrowthRevision, count: math.count, source: "active_round_ledger" };
  }
  return decorated;
}

function qkBattleGrowthFindAction(runtime, event, recorded) {
  const skill = qkBattleGrowthSkill(event);
  if (recorded) return recorded;
  return [...(runtime?.evidenceActions || [])].reverse().find(action => {
    if (action?.side !== event?.side) return false;
    if (!qkBattleGrowthSkill(action?.skill || action) || qkBattleGrowthSkill(action?.skill || action)?.skillId !== skill?.skillId) return false;
    if (event?.actionKey) return action.actionKey === event.actionKey;
    return Number(action?.round) === Number(event?.round ?? runtime?.turn);
  }) || null;
}

function qkFreezeBattleGrowth(runtime, event, recorded) {
  if (!runtime || event?.type !== "skill_cast") return null;
  const skill = qkBattleGrowthSkill(event);
  if (!skill) return null;
  const freezeActorKey = qkBattleGrowthActorKey(runtime, event, event.side);
  const observedAction = qkBattleGrowthFindAction(runtime, event, recorded);
  const observed = event?.qkBattleGrowthObservedCount ?? event?.skill?.qkBattleGrowthObservedCount;
  if (qkBattleGrowthIsSpectator(runtime) && observedAction && observed != null && Number.isFinite(Number(observed))) {
    observedAction.qkBattleGrowthObservedCount = Math.max(0, Math.round(Number(observed)));
    observedAction.skill = { ...observedAction.skill, qkBattleGrowthObservedCount: observedAction.qkBattleGrowthObservedCount };
  }
  if (!qkBattleGrowthEnabled(runtime, skill.skillId, freezeActorKey)) return null;
  if (event?.qkBattleGrowthCount == null) return null;
  let count = Number(event?.qkBattleGrowthCount);
  if (!Number.isFinite(count) || count < 0) return null;
  // Historical casts use the first calibration floor, never the latest live tier.
  if (qkBattleGrowthIsSpectator(runtime) && !skill.resetAfterUse) {
    const freezeTier = qkBattleGrowthActivation(runtime, skill.skillId, freezeActorKey)?.freezeCount;
    if (freezeTier != null && freezeTier > count) count = freezeTier;
  }
  const action = qkBattleGrowthFindAction(runtime, event, recorded);
  if (!action) return null;
  const math = qkBattleGrowthBonusFromCount(skill, count);
  const blob = {
    revision: qkBattleGrowthRevision,
    skillId: skill.skillId,
    count: math.count,
    bonus: math.bonus,
    effectivePower: math.effective,
    source: "action_start",
    eventKey: event.actionKey ?? event.eventKey ?? event.id ?? null
  };
  action.qkBattleGrowthCount = math.count;
  action.qkBattleGrowth = blob;
  action.skill = { ...action.skill, qkBattleGrowthCount: math.count, qkBattleGrowth: blob };
  if (skill.skillId === 7040250) {
    action.qkMountainFireOtherFireCountV374 = math.count;
    action.qkMountainFireV374 = { revision: qkBattleGrowthRevision, otherFireCount: math.count, multiplier: math.multiplier, effectivePower: math.effective, source: "action_start" };
    action.skill = { ...action.skill, qkMountainFireOtherFireCountV374: math.count, qkMountainFireV374: action.qkMountainFireV374 };
  }
  if (skill.skillId === 7020570) {
    action.qkEnergyBladeCounterCountV379 = math.count;
    action.qkEnergyBladeV379 = { revision: qkBattleGrowthRevision, counterCount: math.count, powerBonus: math.bonus, effectivePower: math.effective, source: "action_start" };
    action.skill = { ...action.skill, qkEnergyBladeCounterCountV379: math.count, qkEnergyBladeV379: action.qkEnergyBladeV379 };
  }
  if (skill.skillId === 7150350) {
    action.qkTravelFirstActionCountV383 = math.count;
    action.qkTravelV383 = { revision: qkBattleGrowthRevision, firstActionCount: math.count, powerBonus: math.bonus, effectivePower: math.effective, source: "action_start" };
    action.skill = { ...action.skill, qkTravelFirstActionCountV383: math.count, qkTravelV383: action.qkTravelV383 };
  }
  if (skill.skillId === 7050300) {
    action.qkWaterWaveRoundCount = math.count;
    action.qkWaterWaveRound = { revision: qkBattleGrowthRevision, count: math.count, source: "action_start" };
    action.skill = { ...action.skill, qkWaterWaveRoundCount: math.count, qkWaterWaveRound: action.qkWaterWaveRound };
  }
  for (const impact of action.impacts || []) {
    impact.qkBattleGrowthCount = math.count;
    impact.qkBattleGrowth = blob;
  }
  return blob;
}


function qkApplyBattleGrowthPower(options, move, count, source, runtime, side) {
  const skill = qkBattleGrowthSkill(move);
  if (!options || !skill || options.qkBattleGrowthApplied) return 0;
  if (skill.skillId === 7070020 && (side === "enemy" || options.side === "enemy")) return 0;
  if (count == null || !Number.isFinite(Number(count))) return 0;
  const math = qkBattleGrowthBonusFromCount(skill, count);
  const base = Number(move?.power ?? skill.basePower) || skill.basePower;
  const bonus = skill.kind === qkBattleGrowthKind.MULTIPLIER ? base * (math.multiplier - 1) : math.bonus;
  if (!Number.isFinite(bonus)) return 0;
  options.flatPowerBonus = Number(options.flatPowerBonus || 0) + bonus;
  options.qkBattleGrowthApplied = true;
  options.qkBattleGrowthCount = math.count;
  options.qkBattleGrowthBonus = bonus;
  options.qkBattleGrowthEffectivePower = base + (skill.kind === qkBattleGrowthKind.MULTIPLIER ? bonus : math.bonus);
  if (skill.kind === qkBattleGrowthKind.MULTIPLIER) options.qkBattleGrowthEffectivePower = base * math.multiplier;
  options.qkBattleGrowthSource = source || "unknown";
  options.qkBattleGrowthRevision = qkBattleGrowthRevision;
  if (skill.skillId === 7040250) {
    options.qkMountainFireAppliedV374 = true;
    options.qkMountainFireOtherFireCountV374 = math.count;
    options.qkMountainFirePowerMultiplierV374 = math.multiplier;
    options.qkMountainFireEffectivePowerV374 = options.qkBattleGrowthEffectivePower;
  }
  if (skill.skillId === 7020570) {
    options.qkEnergyBladeAppliedV379 = true;
    options.qkEnergyBladeCounterCountV379 = math.count;
    options.qkEnergyBladePowerBonusV379 = bonus;
    options.qkEnergyBladeEffectivePowerV379 = options.qkBattleGrowthEffectivePower;
  }
  if (skill.skillId === 7150350) {
    options.qkTravelAppliedV383 = true;
    options.qkTravelFirstActionCountV383 = math.count;
    options.qkTravelPowerBonusV383 = bonus;
    options.qkTravelEffectivePowerV383 = options.qkBattleGrowthEffectivePower;
  }
  if (skill.skillId === 7050300) {
    options.qkWaterWaveRoundCount = math.count;
    options.qkWaterWavePowerBonus = bonus;
  }
  return bonus;
}

function qkReplaceBattleGrowthPower(options, move, snapshotCount, liveCount) {
  const skill = qkBattleGrowthSkill(move);
  if (!options || !skill || liveCount == null) return options;
  const previous = Math.max(0, Math.round(Number(options.qkBattleGrowthCount ?? snapshotCount) || 0));
  const next = Math.max(0, Math.round(Number(liveCount) || 0));
  const prevMath = qkBattleGrowthBonusFromCount(skill, previous);
  const base = Number(move?.power ?? skill.basePower) || skill.basePower;
  const prevBonus = skill.kind === qkBattleGrowthKind.MULTIPLIER ? base * (prevMath.multiplier - 1) : prevMath.bonus;
  options.flatPowerBonus = Number(options.flatPowerBonus || 0) - prevBonus;
  options.qkBattleGrowthApplied = false;
  qkApplyBattleGrowthPower(options, move, next, "live_ledger_after_snapshot");
  return options;
}

function qkWaterWaveCountForRef(runtime, side, ref) {
  return qkBattleGrowthCount(runtime, 7050300, qkBattleGrowthActorKey(runtime, ref, side));
}

// qkNeedleOfficialRuleV447: 绵里藏针层数直接读账本（与 qkWaterWaveCountForRef 同源）。
// 层数由 qkBattleGrowthAdvanceNeedle 在每次使用时按官方规则写入，不再由 NeedleCount 重算。
function qkNeedleCountForRefV447(runtime, side, ref) {
  return qkBattleGrowthCount(runtime, 7100260, qkBattleGrowthActorKey(runtime, ref, side));
}

function qkWaterWaveSnapshotCount(action) {
  return qkBattleGrowthSnapshotCount(action);
}

